NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Samuel'

CHAPTERS = {
    1: {
        1: 'Torej tam je bil nek mož iz Ramatájim Cofíma, z gore Efrájim in njegovo ime je bilo Elkaná, sin Jeroháma, sinú Elihúja, sinú Tohuja, sinú Cufa, Efrátejec.',
        2: 'Ta je imel dve ženi. Ime ene je bilo Ana in ime druge Penína. Penína je imela otroke, toda Ana ni imela otrok.',
        3: 'Ta mož je vsako leto šel gor iz svojega mesta, da obožuje in žrtvuje Gospodu nad bojevniki v Šilu. In dva Élijeva sinova, Hofní in Pinhás, Gospodova duhovnika, sta bila tam.',
        4: 'Ko je bil čas, da Elkaná daruje, je dal deleže svoji ženi Peníni in vsem njenim sinovom in njenim hčeram,',
        5: 'toda Ani je dal vreden delež, kajti Ano je ljubil. Toda Gospod je zaprl njeno maternico.',
        6: 'Njena nasprotnica jo je boleče dražila, da bi jo razburila, ker je Gospod zaprl njeno maternico.',
        7: 'Ko je tako delala leto za letom, ko je šla gor do Gospodove hiše, jo je tako razdražila; zato je jokala in ni jedla.',
        8: 'Potem ji je njen soprog Elkaná rekel: »Ana, zakaj jokaš? Zakaj ne ješ? Zakaj je tvoje srce užaloščeno? Ali ti nisem boljši kakor deset sinov?«',
        9: 'Tako je Ana vstala, potem ko so v Šilu pojedli in popili. Torej duhovnik Éli je sedel na sedežu pri podboju Gospodovega templja.',
        10: 'Ona pa je bila v grenkobi duše in molila h Gospodu in bridko jokala.',
        11: 'Zaobljubila je zaobljubo in rekla: »Oh Gospod nad bojevniki, če zares hočeš pogledati na stisko svoje pomočnice in se me spomniš in ne pozabiš svoje pomočnice, temveč hočeš svoji pomočnici dati fantka, potem ga bom izročila Gospodu [za] vse dni njegovega življenja in britev ne bo prišla na njegovo glavo.«',
        12: 'Pripetilo se je, ko je nadaljevala moleč pred Gospodom, da je Éli opazil njena usta.',
        13: 'Torej Ana, ona je govorila v svojem srcu, premikale pa so se samo njene ustnice, toda njenega glasu ni bilo slišati. Zato je Éli mislil, da je bila pijana.',
        14: 'Éli ji je rekel: »Doklej boš pijana? Odloži svoje vino od sebe.«',
        15: 'Ana je odgovorila in rekla: »Ne, moj gospod, jaz sem ženska žalostnega duha. Niti nisem pila vina niti močne pijače, temveč sem svojo dušo izlila pred Gospodom.',
        16: '§ Svoje pomočnice ne štej za Beliálovo hčer, kajti iz obilja svoje pritožbe in žalosti sem doslej govorila.«',
        17: 'Potem je Éli odgovoril in rekel: »Pojdi v miru in Izraelov Bog ti zagotovi prošnjo, ki si jo prosila od njega.«',
        18: 'Rekla je: »Naj tvoja pomočnica najde milost v tvojem pogledu.« Tako je ženska odšla svojo pot in jedla in njeno obličje ni bilo več žalostno.',
        19: 'Vstali so zgodaj zjutraj in oboževali pred Gospodom in se vrnili in prišli k svoji hiši v Ramo. Elkaná je spoznal svojo ženo Ano in Gospod se jo je spomnil.',
        20: 'Zato se je pripetilo, ko je prišel čas, potem ko je Ana spočela, da je rodila sina in njegovo ime je imenovala Samuel, rekoč: »Ker sem ga prosila od Gospoda.«',
        21: 'Mož Elkaná in vsa njegova hiša, so odšli gor, da darujejo Gospodu letno klavno daritev in svojo zaobljubo.',
        22: 'Toda Ana ni odšla gor, kajti svojemu soprogu je rekla: » Ne bom šla gor, dokler ne bo otrok odstavljen in tedaj ga bom privedla, da se prikaže pred Gospodom in tam ostane za vedno.«',
        23: 'Njen soprog Elkaná ji je rekel: »Stôri, kar se ti zdi dobro. Ostani, dokler ga ne odstaviš. Samo Gospod [naj] uveljavi svojo besedo.« Tako je ženska ostala in dojila svojega sina, dokler ga ni odstavila.',
        24: 'Ko ga je odstavila, ga je s seboj vzela gor, s tremi bikci, enim škafom moke in mehom vina ter ga privedla v Gospodovo hišo v Šilo. Otrok pa je bil mlad.',
        25: 'Usmrtili so bikca in otroka privedli k Éliju.',
        26: 'Rekla je: »Oh moj gospod, kakor živi tvoja duša, moj gospod, jaz sem ženska, ki je stala tukaj pri tebi, moleč h Gospodu.',
        27: 'Za tega otroka sem molila in Gospod mi je izpolnil prošnjo, ki sem jo prosila od njega,',
        28: 'zato sem ga tudi posodila Gospodu. Kakor dolgo živi, bo posojen Gospodu.« In tam je oboževal Gospoda.',
    },
    2: {
        1: 'Ana je molila in rekla: »Moje srce se razveseljuje v Gospodu, moj rog je povišan v Gospodu. Moja usta so povečana nad mojimi sovražniki, ker se veselim v tvoji rešitvi duše.',
        2: 'Nihče ni svet kakor Gospod, kajti nikogar ni poleg tebe. Niti ni nobene skale, podobne našemu Bogu.',
        3: 'Ne govorite več tako silno ponosno, naj aroganca ne pride iz vaših ust, kajti Gospod je Bog spoznanja in pri njem so tehtana dejanja.',
        4: 'Loki mogočnih mož so zlomljeni in tisti, ki so se spotaknili, so opasani z močjo.',
        5: 'Tisti, ki so bili siti, so se dali v najem zaradi kruha; tisti, ki so bili lačni, so oslabeli, tako, da je jalova rodila sedmero in tista, ki ima mnogo otrok, je postala slabotna.',
        6: 'Gospod ubija in oživlja. Privede dol do groba in privede gor.',
        7: 'Gospod dela revne in dela bogate, ponižuje in povzdiguje.',
        8: 'Revnega vzdiguje iz prahu in berača povzdiguje iz gnojišča, da ju posadi med prince in jima stori, da podedujeta prestol slave, kajti stebri zemlje so Gospodovi in nanje je postavil zemeljski [krog].',
        9: 'Varoval bo stopala svojih svetih in zlobni bodo tiho v temi, kajti noben človek ne bo prevladal z močjo.',
        10: 'Gospodovi nasprotniki bodo zlomljeni na koščke. Iz nebes bo zagrmel nad njimi. Gospod bo sodil konce zemlje; moč bo dal svojemu kralju in povišal rog svojega maziljenca.«',
        11: 'Elkaná je odšel v Ramo, k svoji hiši. Otrok pa je služil Gospodu pred duhovnikom Élijem.',
        12: 'Torej Élijeva sinova sta bila Beliálova sinova; onadva nista poznala Gospoda.',
        13: 'In običaj duhovnikov z ljudstvom je bil, da ko je katerikoli mož daroval klavno daritev, je prišel duhovnikov služabnik, medtem ko je meso vrelo, s kavljem za meso, s tremi zobmi, v svoji roki;',
        14: 'in to zabodel v ponev ali kotliček ali kotel ali lonec; vse, kar so kavlji za meso prinesli gor, je duhovnik vzel zase. Tako sta počela v Šilu vsem Izraelcem, ki so prihajali tja.',
        15: 'Tudi preden so sežgali tolščo, je prišel duhovnikov služabnik in rekel možu, ki je daroval: »Izroči meso za pečenje duhovniku, kajti od tebe ne bo imel kuhanega mesa, temveč surovega.«',
        16: 'Če pa bi mu katerikoli moški rekel: »Naj ne izpustijo, da sedaj zažgejo tolščo, potem pa vzemi, kolikor si želi tvoja duša;« Potem bi mu odgovoril: » Ne, temveč mi boš to dal sedaj. Če pa ne, bom to vzel s silo.«',
        17: 'Zato je bil greh mladeničev zelo velik pred Gospodom, kajti moža sta prezirala Gospodovo daritev.',
        18: 'Toda Samuel je služil pred Gospodom, ko je bil še otrok, opasan z lanenim efódom.',
        19: 'Poleg tega mu je mati iz leta v leto izdelala majhen plašč in ga prinesla k njemu, ko je prišla gor s svojim soprogom, da daruje letno klavno daritev.',
        20: 'Éli je blagoslovil Elkaná in njegovo ženo ter rekel: » Gospod ti daj seme od te ženske, zaradi posojila, ki je posojen Gospodu.« In odšli so na svoj dom.',
        21: 'Gospod je obiskal Ano, tako da je spočela in rodila [še] tri sinove in dve hčeri. Otrok Samuel pa je rasel pred Gospodom.',
        22: 'Torej Éli je bil zelo star in slišal vse, kar sta njegova sinova počela vsemu Izraelu in kako sta ležala z ženskami, ki so se zbirale pri vratih šotorskega svetišča skupnosti.',
        23: 'Rekel jima je: »Zakaj počneta takšne stvari? Kajti od vsega ljudstva slišim o vajinih zlih postopanjih.',
        24: 'Ne, moja sinova, kajti to ni dober glas, ki ga slišim. Vidva povzročata Gospodovemu ljudstvu, da greši.',
        25: 'Če en mož greši zoper drugega, ga bo sodil sodnik, toda če mož greši zoper Gospoda, kdo bo posredoval zanj.« Vendar nista prisluhnila glasu svojega očeta, ker ju je Gospod hotel ubiti.',
        26: 'Otrok Samuel pa je rasel in bil je v naklonjenosti tako z Gospodom kakor tudi z ljudmi.',
        27: 'K Éliju je prišel Božji mož ter mu rekel: »Tako govori Gospod: ›Ali sem se očitno prikazal hiši tvojega očeta, ko so bili v Egiptu, v faraonovi hiši?',
        28: 'In ali sem ga izbral izmed vseh Izraelovih rodov, da bo moj duhovnik, da daruje na mojem oltarju, da zažiga kadilo, da nosi efód pred menoj? In ali sem dal hiši tvojega očeta vse daritve, narejene z ognjem, Izraelovih otrok?',
        29: 'Zakaj brcate ob mojo klavno daritev in ob mojo daritev, ki sem jo zapovedal v svojem prebivališču in svoja sinova bolj častiš kakor mene, da ste se odebelili z glavnimi izmed vseh daritev Izraela, mojega ljudstva?‹',
        30: 'Zato govori Gospod, Izraelov Bog: ›Zares sem rekel, da naj bi tvoja hiša in hiša tvojega očeta hodili pred menoj na veke.‹ Toda sedaj govori Gospod: ›To bodi daleč od mene, kajti tiste, ki spoštujejo mene, bom jaz spoštoval in tisti, ki me prezirajo, bodo prezirani.',
        31: 'Glej, pridejo dnevi, ko bom odsekal tvoj laket in laket hiše tvojega očeta, da v tvoji hiši ne bo starca.',
        32: '§ In ti boš videl sovražnika v mojem prebivališču v vsem bogastvu, ki ga bo Bog dal Izraelu, in v tvoji hiši na veke ne bo starca.',
        33: 'Moški od tebe, ki ga ne bom odsekal izpred svojega oltarja, bo [preostal], da použije tvoje oči in da žalosti tvoje srce in ves narast tvoje hiše bo umrl v cvetu njihove starosti.',
        34: 'To ti bo znamenje, ki bo prišlo nad tvoja dva sinova, na Hofníja in Pinhása; v enem dnevu bosta oba izmed njiju umrla.',
        35: 'Jaz pa si bom dvignil zvestega duhovnika, ki bo delal glede na to, kar je v mojem srcu in v mojem umu in zgradil mu bom zanesljivo hišo; in ta bo hodil pred mojim maziljencem na veke.',
        36: 'Zgodilo se bo, da bo vsak, kdor preostane v tvoji hiši, prišel in klečeplazil k njemu za košček srebra in grižljaj kruha in rekel bo: ›Postavi me, prosim te, v eno izmed duhovniških služb, da bom lahko jedel kos kruha.‹«',
    },
    3: {
        1: 'Otrok Samuel pa je pred Élijem služil Gospodu. V tistih dneh je bila Gospodova beseda dragocena; ni bilo odprtega videnja.',
        2: 'Pripetilo se je ob tistem času, ko se je Éli ulegel na svojem mestu in so njegove oči začenjale temneti, da ni mogel videti.',
        3: 'Preden se je ugasnila Božja svetilka v Gospodovem templju, kjer je bila Božja skrinja in se je Samuel ulegel k spanju,',
        4: 'je Gospod poklical Samuela in ta je odgovoril: »Tukaj sem.«',
        5: 'Stekel je k Éliju in rekel: »Tukaj sem, kajti klical si me.« Ta pa je rekel: »Nisem klical, ponovno se ulezi.« In odšel je in se ulegel.',
        6: 'Gospod je ponovno poklical: »Samuel.« Samuel je vstal in odšel k Éliju ter rekel: »Tukaj sem, kajti klical si me.« Ta je odgovoril: »Nisem klical, moj sin, ponovno se ulezi.«',
        7: 'Torej Samuel še ni poznal Gospoda niti mu Gospodova beseda še ni bila razodeta.',
        8: 'Gospod je ponovno, tretjič, poklical Samuela. Ta je vstal, šel k Éliju in rekel: »Tukaj sem, kajti klical si me.« In Éli je zaznal, da je otroka klical Gospod.',
        9: 'Zato je Éli rekel Samuelu: »Pojdi, ulezi se in zgodilo se bo, če te pokliče, da boš rekel: ›Govori, Gospod, kajti tvoj služabnik posluša.‹« Tako je Samuel odšel in se ulegel na svojem mestu.',
        10: 'Gospod je prišel in obstal ter poklical kakor ob drugih časih: »Samuel, Samuel.« Potem je Samuel odgovoril: »Govori; kajti tvoj služabnik posluša.«',
        11: 'Gospod je rekel Samuelu: »Glej, storil bom stvar v Izraelu, ob kateri bo v obeh ušesih vsakega, ki to sliši, zvenelo.',
        12: 'Na tisti dan bom zoper Élija izpolnil vse stvari, ki sem jih govoril glede njegove hiše. Ko pričnem, bom naredil tudi konec.',
        13: 'Kajti povedal sem mu, da bom na veke sodil njegovo hišo zaradi krivičnosti, ki jo on vé, ker sta se njegova sinova naredila nizkotna, on pa jima ni preprečil.',
        14: 'Zato sem prisegel Élijevi hiši, da krivičnost Élijeve hiše na veke ne bo očiščena niti s klavno daritvijo niti z darovanjem.«',
        15: 'Samuel je ležal do jutra in odprl vrata Gospodove hiše. Samuel pa se je Éliju bal razodeti videnje.',
        16: 'Potem je Éli poklical Samuela in rekel: »Samuel, moj sin.« Ta je odgovoril: »Tukaj sem.«',
        17: 'Rekel je: »Kaj je stvar, ki ti jo je Gospod povedal? Prosim te, da mi je ne prikriješ. Bog naj ti tako stori in tudi več, če pred menoj skriješ katerokoli stvar od vseh stvari, ki ti jih je povedal.«',
        18: 'Samuel mu je povedal vsak delček in ničesar ni skril pred njim. On pa je rekel: »To je Gospod. Naj stori, kar se mu zdi dobro.«',
        19: 'Samuel je rasel in Gospod je bil z njim in nobene izmed njegovih besed ni pustil pasti na tla.',
        20: 'Ves Izrael, od Dana, celo do Beeršébe, je vedel, da je bil Samuel utrjen, da bi bil Gospodov prerok.',
        21: 'Gospod se je ponovno prikazoval v Šilu, kajti Gospod se je v Šilu razodeval Samuelu po Gospodovi besedi.',
    },
    4: {
        1: 'Beseda od Samuela je prišla k vsemu Izraelu. Torej Izrael je odšel ven zoper Filistejce, da se bojujejo in utaborili so se poleg Eben Ezerja. Filistejci pa so se utaborili v Aféku.',
        2: 'Filistejci so se razporedili zoper Izraela in ko so se pridružili bitki, je bil Izrael udarjen pred Filistejci in usmrtili so izmed vojske na polju okoli štiri tisoč mož.',
        3: 'Ko je ljudstvo prišlo v tabor, so starešine Izraela rekli: »Zakaj nas je Gospod danes udaril pred Filistejci? Skrinjo Gospodove zaveze prinesimo iz Šila k sebi, da ko ta pride med nas, nas ta lahko reši iz roke naših sovražnikov.«',
        4: 'Tako je ljudstvo poslalo v Šilo, da bi od tam lahko prinesli skrinjo zaveze Gospoda nad bojevniki, ki prebiva med kerubi, in Élijeva dva sinova, Hofní in Pinhás, sta bila tam s skrinjo Božje zaveze.',
        5: 'Ko je v tabor prišla skrinja Gospodove zaveze, je ves Izrael vriskal z močnim vriskom, tako da je zemlja ponovno zadonela.',
        6: 'Ko so Filistejci slišali hrup vriska, so rekli: »Kaj pomeni hrup tega močnega vriska v taboru Hebrejcev?« Razumeli so, da je v tabor prišla Gospodova skrinja.',
        7: 'Filistejci so bili prestrašeni, kajti rekli so: »Bog je prišel v tabor.« Rekli so: »Gorje nam! Kajti poprej še ni bilo takšne stvari.',
        8: 'Gorje nam! Kdo nas bo rešil iz roke teh mogočnih Bogov? To so Bogovi, ki so v divjini udarili Egipčane z vsemi nadlogami.',
        9: 'Bodite močni in obnašajte se kakor možje, oh vi Filistejci, da ne bomo služabniki Hebrejcem, kakor so bili oni vam. Obnašajte se kakor možje in se borite.«',
        10: 'Filistejci so se borili in Izrael je bil udarjen in zbežali so vsak mož v svoj šotor, in bil je zelo velik pokol, kajti v Izraelu je padlo trideset tisoč pešcev.',
        11: 'Božja skrinja je bila vzeta in Élijeva dva sinova, Hofní in Pinhás, sta bila ubita.',
        12: 'Mož iz Benjamina pa je stekel iz vojske in še isti dan prišel v Šilo s pretrganimi oblačili in prstjo na svoji glavi.',
        13: 'Ko je prišel, glej, je Éli sedel na sedežu in gledal ob poti, kajti njegovo srce je trepetalo za Božjo skrinjo. Ko je mož prišel v mesto in to povedal, je celotno mesto zavpilo.',
        14: 'Ko je Éli slišal hrup vpitja, je rekel: »Kaj pomeni zvok tega nemira?« Mož je v naglici prišel in povedal Éliju.',
        15: 'Torej Éli je bil star osemindevetdeset let in njegove oči so bile zatemnjene, da ni mogel videti.',
        16: 'Mož je rekel Éliju: »Jaz sem tisti, ki je prišel iz vojske in danes sem pobegnil iz vojske.« On pa je rekel: »Kaj je tam storjeno, moj sin?«',
        17: 'Poslanec je odgovoril in rekel: »Izrael je pobegnil pred Filistejci in tam je bil prav tako velik pokol med ljudstvom in tudi tvoja sinova, Hofní in Pinhás sta mrtva in Božja skrinja je vzeta.«',
        18: 'Pripetilo se je, ko je omenil Božjo skrinjo, da je padel nazaj s stola ob strani velikih vrat in njegov vrat se je zlomil in je umrl, kajti bil je starec in težak. Izraelu je sodil štirideset let.',
        19: 'Njegova snaha, Pinhásova soproga, je bila z otrokom, blizu časa poroda. Ko je slišala novice, da je bila Božja skrinja vzeta in da sta bila njen tast in njen mož mrtva, se je sklonila in bila v porodnih mukah, kajti njene bolečine so prišle nadnjo.',
        20: 'Okoli časa njene smrti so ji ženske, ki so stale ob njej, rekle: »Ne boj se, kajti rodila si sina.« Toda ona ni odgovorila niti se na to ni ozirala.',
        21: 'Otroka je imenovala Ikabód, rekoč: »Slava je odšla od Izraela,« ker je bila Božja skrinja vzeta in zaradi njenega tasta in njenega soproga.',
        22: 'Rekla je: »Slava je odšla od Izraela, kajti Božja skrinja je vzeta.«',
    },
    5: {
        1: 'Filistejci so vzeli Božjo skrinjo in jo iz Eben Ezerja prinesli v Ašdód.',
        2: 'Ko so Filistejci vzeli Božjo skrinjo, so jo prinesli v Dagónovo hišo in jo postavili poleg Dagóna.',
        3: 'Ko so tisti iz Ašdóda naslednji dan zgodaj vstali, glej, Dagón je bil zvrnjen dol k zemlji, na svoj obraz, pred Gospodovo skrinjo. In prijeli so Dagóna in ga ponovno postavili na njegovo mesto.',
        4: 'Ko so naslednji dan zgodaj zjutraj vstali, glej, Dagón je bil zvrnjen na svojem obrazu na tleh pred Gospodovo skrinjo, in Dagónova glava in obe dlani njegovih rok so bili odsekani na pragu. Samo Dagónov trup mu je preostal.',
        5: 'Zato niti Dagónovi duhovniki niti kdorkoli, ki pride v Dagónovo hišo, do današnjega dne, ne stopajo na Dagónov prag v Ašdódu.',
        6: 'Toda Gospodova roka je bila težka nad tistimi iz Ašdóda in uničeval jih je in jih udaril s hemoroídi, torej Ašdód in njegova mesta.',
        7: 'Ko so možje iz Ašdóda videli, da je bilo tako, so rekli: »Skrinja Izraelovega Boga naj ne ostane z nami, kajti njegova roka je boleče nad nami in nad našim bogom Dagónom.«',
        8: 'Zato so poslali in k sebi zbrali vse filistejske kneze ter rekli: »Kaj naj storimo s skrinjo Izraelovega Boga?« Odgovorili so: »Naj bo skrinja Izraelovega Boga prenesena v Gat.« In tja so prenesli skrinjo Izraelovega Boga.',
        9: 'To je bilo tako, da potem, ko so jo odnesli, je bila Gospodova roka zoper mesto z zelo velikim uničenjem in udaril je može iz mesta, tako male, kakor velike in imeli so hemoroíde v svojih skritih delih.',
        10: 'Zato so Božjo skrinjo poslali v Ekrón. Pripetilo se je, ko je Božja skrinja prišla v Ekrón, da so Ekrónci zavpili, rekoč: »K nam so privedli skrinjo Izraelovega Boga, da ubije nas in naše ljudstvo.«',
        11: 'Tako so poslali in zbrali skupaj vse filistejske kneze in rekli: »Pošljite proč skrinjo Izraelovega Boga in naj ponovno gre na svoj kraj, da ne ubije nas in našega ljudstva,« kajti tam je bilo v vsem mestu smrtonosno uničenje. Božja roka je bila tam zelo težka.',
        12: 'Možje, ki niso umrli, so bili udarjeni s hemoroídi in krik mesta je šel gor do neba.',
    },
    6: {
        1: 'Gospodova skrinja je bila v filistejski deželi sedem mesecev.',
        2: 'Filistejci so dali poklicati duhovnike in vedeževalce, rekoč: »Kaj naj storimo z Gospodovo skrinjo? Povejte nam, s čim naj jo pošljemo na njen kraj?«',
        3: 'Rekli so: »Če odpošljete skrinjo Izraelovega Boga, je ne pošljite prazne; temveč mu na vsak način vrnite daritev za prestopek. Potem boste ozdravljeni in znano vam bo zakaj njegova roka ni odstranjena od vas.«',
        4: 'Potem so rekli: »Kakšna naj bo daritev za prestopek, ki mu jo bomo vrnili?« Odgovorili so: »Pet zlatih hemoroídov in pet zlatih miši, glede na število filistejskih knezov, kajti ena nadloga je bila na vas vseh in na vaših gospodarjih.',
        5: 'Zato boste naredili podobe vaših tvorov in podobe vaših miši, ki uničujejo deželo in dali boste slavo Izraelovemu Bogu. Morda bo olajšal svojo roko iznad vas in iznad vaših bogov in iznad vaše dežele.',
        6: 'Zakaj bi torej zakrknili svoja srca, kakor so Egipčani in faraon zakrknili svoja srca? Ko je izvrstno delal med njimi, ali niso pustili ljudstva iti in so odpotovali?',
        7: 'Zdaj torej naredite nov voz in vzemite dve doječi kravi, na kateri jarem ni prišel in kravi privežite k vozu, njuna telička pa od njiju odvedite domov',
        8: 'in vzemite Gospodovo skrinjo in jo položite na voz in položite dragocenosti iz zlata, ki mu jih vračate za daritev za prestopek, v skrinjico ob njeni strani in pošljite jo proč, da bo ta lahko odšla.',
        9: 'Glejte, če gre ta gor po poti svojega lastnega območja v Bet Šemeš, potem nam je on storil to veliko zlo, toda če ne, potem bomo vedeli, da to ni njegova roka, ki nas je udarila; to je bilo naključje, ki se nam je pripetilo.«',
        10: 'Ljudje so tako storili. Vzeli so dve doječi kravi ter ju privezali k vozu, njuni teleti pa zaprli doma.',
        11: 'Gospodovo skrinjo so položili na voz in skrinjico z mišmi iz zlata in podobami svojih hemoroídov.',
        12: 'Kravi sta šli naravnost na pot Bet Šemeša in šli sta vzdolž glavne ceste, mukajoč, medtem ko sta hodili in nista se obračali vstran ne na desno roko ne na levo in filistejski knezi so šli za njima do meje Bet Šemeša.',
        13: 'Tisti iz Bet Šemeša so v dolini želi svojo pšenično žetev in povzdignili so svoje oči in zagledali skrinjo in se razveselili, da jo vidijo.',
        14: 'Voz je prišel na polje Bétšémeščana Jošúa in obstal tam, kjer je bil velik kamen in nacepili so les od voza in kravi darovali v žgalno daritev Gospodu.',
        15: 'Lévijevci so sneli Gospodovo skrinjo in skrinjico, ki je bila z njo, v kateri so bile dragocenosti iz zlata in ju položili na velik kamen in možje iz Bet Šemeša so isti dan Gospodu darovali žgalne daritve in žrtvovali klavne daritve.',
        16: 'Ko je pet filistejskih knezov to videlo, so se istega dne vrnili v Ekrón.',
        17: 'To pa so zlati hemoroídi, ki so jih Filistejci vrnili Gospodu za daritev za prestopek: enega za Ašdód, enega za Gazo, enega za Aškelón, enega za Gat, enega za Ekrón;',
        18: 'in zlate miši glede na število vseh filistejskih mest, pripadajočih petim knezom, tako utrjenih mest kakor podeželskih vasi, celo do velikega Abelovega kamna, na katerega so položili Gospodovo skrinjo; katerega kamen ostaja na polju Bétšémeščana Jošúa do današnjega dne.',
        19: '§ Udaril pa je može iz Bet Šemeša, ker so gledali v Gospodovo skrinjo, torej izmed ljudstva je udaril petdeset tisoč in sedemdeset mož in ljudstvo je žalovalo, ker je Gospod z velikim pokolom udaril mnoge izmed ljudstva.',
        20: 'Možje iz Bet Šemeša so rekli: »Kdo je zmožen stati pred tem svetim Gospodom Bogom? In h komu naj gre gor od nas?«',
        21: 'Poslali so poslance k prebivalcem Kirját Jearíma, rekoč: »Filistejci so ponovno privedli Gospodovo skrinjo. Pridite dol in jo prenesite gor k sebi.«',
    },
    7: {
        1: 'Možje iz Kirját Jearíma so prišli in prenesli gor Gospodovo skrinjo in jo prinesli v Abinadábovo hišo na hribu in posvetili njegovega sina Eleazarja, da varuje Gospodovo skrinjo.',
        2: 'Pripetilo se je, medtem ko je skrinja prebivala v Kirját Jearímu, da je bil čas dolg, kajti to je bilo dvajset let. Vsa Izraelova hiša je žalovala za Gospodom.',
        3: 'Samuel je govoril vsej Izraelovi hiši, rekoč: »Če se z vsemi svojimi srci vrnete h Gospodu, potem izmed sebe odstranite tuje bogove in Astarto in pripravite svoja srca h Gospodu in samo njemu služite. On vas bo osvobodil iz roke Filistejcev.«',
        4: 'Potem so Izraelovi otroci odstranili Báale in Astarto in služili samo Gospodu.',
        5: 'Samuel je rekel: »Zberite ves Izrael v Micpi in jaz bom za vas molil h Gospodu.«',
        6: 'Zbrali so se skupaj v Micpi, zajeli vodo in jo izlili pred Gospodom in se postili na ta dan in tam rekli: »Grešili smo zoper Gospoda.« In Samuel je sodil Izraelove otroke v Micpi.',
        7: 'Ko so Filistejci slišali, da so se Izraelovi otroci zbrali skupaj k Micpi, so filistejski knezi odšli gor zoper Izrael. Ko so Izraelovi otroci to slišali, so se bali Filistejcev.',
        8: 'Izraelovi otroci so rekli Samuelu: »Ne odnehaj klicati h Gospodu, našemu Bogu za nas, da nas bo rešil iz roke Filistejcev.«',
        9: 'Samuel je vzel sesajoče jagnje in ga v celoti daroval v žgalno daritev Gospodu. Samuel je klical h Gospodu za Izrael in Gospod ga je slišal.',
        10: 'Medtem ko je Samuel daroval žgalno daritev, so se približali Filistejci, da se bojujejo zoper Izrael, toda Gospod je na ta dan z velikim gromom zagrmel nad Filistejci in jih porazil in udarjeni so bili pred Izraelom.',
        11: 'Možje iz Izraela so odšli ven iz Micpe in zasledovali Filistejce in jih udarjali, dokler niso prišli pod Bet Kar.',
        12: 'Potem je Samuel vzel kamen in ga postavil med Micpo in Jašén in njegovo ime imenoval Eben Ezer, rekoč: »Doslej nam je Gospod pomagal.«',
        13: 'Tako so bili Filistejci podjarmljeni in niso več prišli v območje Izraela in Gospodova roka je bila zoper Filistejce vse Samuelove dni.',
        14: 'Mesta, ki so jih Filistejci vzeli od Izraela, so bila povrnjena Izraelu, od Ekróna, celo do Gata in njihova območja je Izrael osvobodil iz rok Filistejcev. In bil je mir med Izraelom in Amoréjci.',
        15: 'Samuel je sodil Izraelu vse dni svojega življenja.',
        16: 'Iz leta v leto je odšel na obhod do Betela in Gilgála in Micpe in na vseh teh krajih sodil Izraelu.',
        17: 'Njegova vrnitev je bila v Ramo, kajti tam je bila njegova hiša in tam je sodil Izraelu in tam je zgradil oltar Gospodu.',
    },
    8: {
        1: 'Pripetilo se je, ko je bil Samuel star, da je svoja sinova postavil za sodnika nad Izraelom.',
        2: 'Torej ime njegovega prvorojenca je bilo Joél in ime njegovega drugega Abíja. Bila sta sodnika v Beeršébi.',
        3: 'Njegova sinova pa nista hodila po njegovih poteh, temveč sta se obrnila stran za dobičkom in jemala podkupnine in izkrivljala sodbo.',
        4: 'Potem so se vse starešine Izraela zbrali skupaj in prišli k Samuelu v Ramo',
        5: 'in mu rekli: »Glej, star si in tvoja sinova ne hodita po tvojih poteh. Sedaj nam postavi kralja, da nas sodi, kakor [imajo] vsi narodi.«',
        6: 'Toda stvar je razžalila Samuela, ko so rekli: »Daj nam kralja, da nas sodi.« Samuel je molil h Gospodu.',
        7: 'Gospod je rekel Samuelu: »Prisluhni glasu ljudstva v vsem, kar ti rečejo, kajti niso zavrnili tebe, temveč so zavrnili mene, da ne bi kraljeval nad njimi.',
        8: 'Glede na vsa dela, ki so jih storili od dne, ko sem jih privedel gor iz Egipta, celo do tega dne, s čimer so zapustili mene in služili drugim bogovom, tako delajo tudi tebi.',
        9: 'Zdaj torej prisluhni njihovemu glasu, vendar jih slovesno posvari in jim pokaži navade kralja, ki bo kraljeval nad njimi.«',
        10: 'Samuel je ljudstvu, ki je od njega zahtevalo kralja, povedal vse Gospodove besede.',
        11: 'Rekel je: »To bo navada kralja, ki bo kraljeval nad vami: ›Vzel bo vaše sinove in jih določil zase, za svoje bojne vozove in da bodo njegovi konjeniki in nekateri bodo tekli pred njegovimi bojnimi vozovi.',
        12: 'Določil si bo tisočnike in poveljnike nad petdesetimi in postavil jih bo, da orjejo njegovo zemljo, da žanjejo njegovo žetev, da izdelajo njegova bojna orodja in orodja njegovih bojnih vozov.',
        13: 'Vzel bo vaše hčere, da bodo izdelovalke dišečin in da bodo kuharice in pekarice.',
        14: 'Vzel bo vaša polja in vaše vinograde in vaše oljčne nasade, celó najboljše izmed njih in jih dal svojim služabnikom.',
        15: 'Vzel bo desetino od vašega semena in od vaših vinogradov in dal svojim častnikom in svojim služabnikom.',
        16: 'Vzel bo vaše služabnike, vaše dekle, vaše najčednejše mladeniče, vaše osle in jih postavil k svojemu delu.',
        17: 'Vzel bo desetino od vaših ovc in vi boste njegovi služabniki.',
        18: 'Vpili boste na ta dan zaradi svojega kralja, ki si ga boste izbrali, Gospod pa vas na ta dan ne bo slišal.‹«',
        19: 'Kljub temu je ljudstvo odklonilo, da uboga Samuelov glas in rekli so: »Ne, temveč bomo imeli kralja nad seboj,',
        20: 'da bomo tudi mi lahko podobni vsem narodom in da nam bo naš kralj lahko sodil in bo pred nami šel ven in bojeval naše boje.«',
        21: 'Samuel je slišal vse besede ljudstva in jih ponovil v Gospodova ušesa.',
        22: 'Gospod je Samuelu rekel: »Prisluhni njihovemu glasu in postavi jim kralja.« Samuel je rekel Izraelovim možem: »Pojdite vsak mož v svoje mesto.«',
    },
    9: {
        1: 'Torej tam je bil mož iz Benjamina, katerega ime je bilo Kiš, sin Abiéla, sinú Cerórja, sinú Behoráta, sinú Afíaha, Benjaminovec, mogočen človek moči.',
        2: 'Imel je sina, čigar ime je bilo Savel, izbranega in čednega mladeniča in med Izraelovimi otroki ni bilo čednejše osebe kakor on. Od njegovih ramen in navzgor je bil višji kakor katerikoli izmed ljudstva.',
        3: 'Oslice Savlovega očeta Kiša so se izgubile. Kiš je rekel svojemu sinu Savlu: »Vzemi torej s seboj enega izmed služabnikov in vstani, pojdi iskat oslice.«',
        4: 'Prečkal je goro Efrájim in šel skozi deželo Šalíša, toda nista jih našla. Potem sta šla skozi deželo Šaalím in tam jih ni bilo. Šel je skozi deželo Benjaminovcev, toda nista jih našla.',
        5: 'In ko sta prišla do dežele Cuf, je Savel rekel svojemu služabniku, ki je bil z njim: »Pridi in se vrniva, da ne bi moj oče prenehal skrbeti za oslice in bi mislil na naju.«',
        6: 'Rekel mu je: »Glej torej, v tem mestu je Božji mož in ta je častitljiv mož. Vse, kar reče, se zagotovo zgodi. Pojdiva sedaj tja, morda nama on lahko pokaže pot, po kateri naj greva.«',
        7: 'Potem je Savel rekel svojemu služabniku: »Toda glej, če greva, kaj bova prinesla možu? Kajti kruh v najinih posodah je pošel in ni darila, da bi ga prinesla Božjemu možu. Kaj imava?«',
        8: 'Služabnik je ponovno odgovoril Savlu in rekel: »Glej, tukaj pri roki imam četrtinko šekla srebra. To bom dal Božjemu možu, da nama pove najino pot.«',
        9: '(Poprej je v Izraelu mož, ko je šel, da poizveduje od Boga, govoril tako: »Pridite in pojdimo k vidcu,« kajti kdor je sedaj imenovan prerok, je bil poprej imenovan videc.)',
        10: 'Potem je Savel rekel svojemu služabniku: »Dobro rečeno. Pridi, pojdiva.« Tako sta šla v mesto, kjer je bil Božji mož.',
        11: 'In ko sta šla gor, po hribu do mesta, sta našla mladenke, ki so prihajale ven, da zajamejo vodo in rekla sta jim: »Je tukaj videc?«',
        12: 'Odgovorile so jima in rekle: »Je, glejta, pred vama je. Sedaj pohitita, kajti danes je prišel v mesto, kajti danes je klavna daritev ljudstva na visokem kraju.',
        13: 'Takoj ko prideta v mesto, ga bosta nemudoma našla, preden gre gor na visok kraj, da jé, kajti ljudstvo ne bo jedlo, dokler on ne pride, ker on blagoslovi klavno daritev in potem tisti, ki so povabljeni, jedo. Sedaj torej pojdita gor, kajti približno ta čas ga bosta našla.«',
        14: 'Šla sta gor v mesto in ko sta prišla v mesto, glej, je Samuel prihajal ven proti njima, da bi šel gor na visok kraj.',
        15: 'Torej Gospod je Samuelu na uho povedal, dan poprej, preden je Savel prišel, rekoč:',
        16: '»Jutri okrog tega časa ti bom poslal moža iz Benjaminove dežele in ti ga boš mazilil, da bo poveljnik nad mojim ljudstvom Izraelom, da bo lahko rešil moje ljudstvo iz roke Filistejcev, kajti jaz sem pogledal na svoje ljudstvo, ker je njihov krik prišel k meni.«',
        17: 'Ko je Samuel zagledal Savla, mu je Gospod rekel: »Glej mož, o katerem sem ti govoril! Ta isti bo kraljeval nad mojim ljudstvom.«',
        18: 'Potem se je Savel približal k Samuelu v velikih vratih in rekel: »Povej mi, prosim te, kje je vidčeva hiša.«',
        19: 'Samuel je odgovoril Savlu in rekel: »Jaz sem videc. Pojdi gor pred menoj na visok kraj, kajti danes boš jedel z menoj, jutri pa te bom pustil oditi in povedal ti bom vse, kar je v tvojem srcu.',
        20: 'Glede oslic, ki so bile izgubljene pred tremi dnevi, ne naravnaj svojih misli nanje, kajti najdene so. Na kom je vse hrepenenje Izraela? Ali ni na tebi in na vsej hiši tvojega očeta?«',
        21: 'Savel je odgovoril in rekel: » Ali nisem Benjaminovec, od najmanjšega izmed Izraelovih rodov? In moja družina najmanjša izmed vseh družin Benjaminovega rodu? Zakaj mi potem tako govoriš?«',
        22: 'Samuel je vzel Savla in njegovega služabnika ter ju privedel v dvorano in ju primoral sesti na najvišje mesto med tistimi, ki so bili povabljeni, katerih je bilo približno trideset oseb.',
        23: 'Samuel je rekel kuharju: »Prinesi delež, ki sem ti ga dal, od katerega sem ti rekel: ›Postavi to poleg sebe.‹«',
        24: 'Kuhar je vzel pleče in tisto, kar je bilo na njem in to postavil pred Savla. Samuel je rekel: »Glej to, kar je preostalo! Postavi to predse in jej, kajti za ta čas je bilo prihranjeno zate, odkar sem rekel: ›Povabil sem ljudstvo.‹« Tako je Savel tisti dan jedel s Samuelom.',
        25: 'Ko sta prišla dol iz visokega kraja v mesto, se je Samuel s Savlom posvetoval na vrhu hiše.',
        26: 'Zgodaj so vstali in pripetilo se je ob svitanju dneva, da je Samuel poklical Savla na vrhu hiše, rekoč: »Vstani, da te lahko odpošljem.« Savel je vstal in odšla sta ven, oba izmed njiju, on in Samuel.',
        27: 'In ko sta se spuščala dol, do konca mesta, je Samuel rekel Savlu: »Zapovej služabniku, da gre naprej pred nama (in ta je šel naprej), toda ti malce postoj, da ti lahko pokažem besedo od Boga.«',
    },
    10: {
        1: 'Potem je Samuel vzel stekleničko olja in jo izlil na njegovo glavo ter ga poljubil in rekel: » Ali ni to zato, ker te je Gospod mazilil, da bi bil poveljnik nad njegovo dediščino?',
        2: 'Ko danes odideš od mene, potem boš našel dva moža ob Rahelinem mavzoleju, na meji Benjamina, ob Celcáhu; in rekla ti bosta: ›Oslice, ki si jih šel iskat, so najdene in glej, tvoj oče je zapustil skrb nad oslicami in se žalosti zaradi tebe, rekoč: ›Kaj naj storim za svojega sina?‹‹',
        3: 'Potem boš šel naprej od tam in prišel boš do ravnine Tabor in tam boš srečal tri može, ki gredo gor k Bogu v Betel. Eden bo nosil tri kozličke, drugi bo nosil tri hlebe kruha in drugi bo nosil vinski meh.',
        4: 'Pozdravili te bodo in ti dali dva hleba kruha, ki ju boš sprejel iz njihovih rok.',
        5: 'Potem boš prišel do Božjega hriba, kjer je garnizija Filistejcev in zgodilo se bo, ko prideš tja do mesta, da boš srečal skupino prerokov prihajati dol iz visokega kraja, s plunko, bobničem, piščaljo in harfo pred njimi, in oni bodo prerokovali.',
        6: 'Gospodov Duh bo prišel nadte in prerokoval boš z njimi in spremenjen boš v drugega človeka.',
        7: 'Naj bo, ko pridejo k tebi ta znamenja, da storiš, kakor se ti ponuja priložnost, kajti Bog je s teboj.',
        8: 'Šel boš dol pred menoj v Gilgál, in glej, prišel bom dol k tebi, da darujem žgalne daritve in da žrtvujem žrtvovanje mirovnih daritev. Sedem dni boš čakal, dokler ne pridem k tebi in ti pokažem, kaj boš storil.«',
        9: 'Bilo je tako, da ko je obrnil hrbet, da bi odšel od Samuela, mu je Bog dal drugo srce in vsa ta znamenja so se zgodila tisti dan.',
        10: 'Ko so prišli tja do hriba, glej, ga je srečala skupina prerokov in Božji Duh je prišel nadenj in prerokoval je med njimi.',
        11: 'Pripetilo se je, ko so vsi, ki so ga poznali od prej, videli, da je, glej, prerokoval med preroki, potem je ljudstvo reklo drug drugemu: »Kaj je to, kar je prišlo h Kiševemu sinu? Ali je tudi Savel med preroki?«',
        12: 'Nekdo iz istega kraja je odgovoril in rekel: »Toda kdo je njihov oče?« Zato je postal pregovor: »Ali je tudi Savel med preroki?«',
        13: 'Ko je nehal prerokovati, je prišel na visok kraj.',
        14: 'Savlov stric je rekel njemu in njegovemu služabniku: »Kam sta odšla?« Rekel je: »Iskat oslice. Ko pa sva videla, da jih ni bilo nikjer, sva šla k Samuelu.«',
        15: 'Savlov stric je rekel: »Povej mi, prosim te, kaj ti je Samuel rekel.«',
        16: 'Savel je svojemu stricu rekel: »Pojasnil nama je, da so bile oslice najdene.« Toda o zadevi kraljestva, o kateri je govoril Samuel, mu ni povedal.',
        17: 'Samuel je skupaj sklical ljudstvo h Gospodu v Micpo',
        18: 'in Izraelovim otrokom rekel: »Tako govori Gospod, Izraelov Bog: ›Izraela sem privedel iz Egipta in vas osvobodil iz roke Egipčanov in iz roke vseh kraljestev in od teh, ki so vas zatirali,‹',
        19: 'vi pa ste ta dan zavrnili svojega Boga, ki vas je sam rešil vseh vaših nasprotnikov in vaših stisk in ste mu rekli: › Ne, temveč nad nami postavi kralja.‹ Sedaj se torej predstavite pred Gospodom po vaših rodovih in po vaših tisočih.«',
        20: 'Ko je Samuel vsem Izraelovim rodovom velel, da se približajo, je bil izbran Benjaminov rod.',
        21: 'Ko je Benjaminovemu rodu velel, da pride bliže po svojih družinah, je bila izbrana Matríjeva družina in izbran je bil Kišev sin Savel. Ko pa so ga iskali, ga niso mogli najti.',
        22: 'Zato so naprej povpraševali od Gospoda, ali bi mož še moral priti tja. Gospod je odgovoril: »Glejte, skril se je med stvari.«',
        23: 'Stekli so in ga vzeli od tam. Ko je stal med ljudstvom, je bil višji kakor katerikoli izmed ljudstva, od njegovih ramen navzgor.',
        24: 'Samuel je vsemu ljudstvu rekel: »Vidite koga je Gospod izbral, da tu ni podobnega njemu izmed vsega ljudstva?« Vse ljudstvo je zavpilo in reklo: »Živel kralj.«',
        25: 'Potem je Samuel ljudstvu povedal o načinu kraljestva in to zapisal v knjigo ter jo položil pred Gospoda. In Samuel je vse ljudstvo poslal proč, vsakega k svoji hiši.',
        26: 'Tudi Savel je odšel domov v Gíbeo in z njim je šla četa mož, čigar src se je Bog dotaknil.',
        27: 'Toda Beliálovi otroci so rekli: »Kako nas bo ta človek rešil?« Prezirali so ga in mu niso prinesli daril. Toda on je ohranil svoj mir.',
    },
    11: {
        1: 'Potem je prišel gor Amónec Naháš in se utaboril zoper Jabéš Gileád. Vsi možje Jabéša so rekli Nahášu: »Skleni zavezo z nami in mi ti bomo služili.«',
        2: 'Amónec Naháš jim je odgovoril: »Pod tem pogojem bom sklenil zavezo z vami, da vam lahko iztaknem vsa vaša desna očesa in to položim za grajo nad ves Izrael.«',
        3: 'Starešine iz Jabéša so mu rekli: »Daj nam sedem dni predaha, da lahko odpošljemo poslance v vse Izraelove pokrajine, in potem, če ne bo nobenega človeka, da nas reši, bomo prišli ven k tebi.«',
        4: 'Potem sta poslanca prišla v Savlovo Gíbeo in v ušesa ljudstva povedala novice in vse ljudstvo je povzdignilo svoje glasove ter zajokalo.',
        5: 'Glej, Savel je prišel za čredo iz polja in Savel je rekel: »Kaj pesti ljudstvo, da jokajo?« Povedali so mu novice od ljudi iz Jabéša.',
        6: 'Božji Duh je prišel nad Savla, ko je slišal tiste novice in njegova jeza je bila silno vneta.',
        7: 'Snel je jarem iz volov in ju razsekal na koščke in le-te poslal po vseh Izraelovih pokrajinah, po rokah poslancev, rekoč: »Kdorkoli ne pride naprej za Savlom in Samuelom, bo tako storjeno njegovim volom.« Gospodov strah je padel na ljudstvo in prišli so ven soglasno.',
        8: 'Ko jih je preštel v Bezeku, je bilo Izraelovih otrok tristo tisoč in Judovih mož trideset tisoč.',
        9: 'Poslancem, ki so prišli, so povedali: »Tako boste rekli možem iz Jabéš Gileáda: ›Jutri, ob času, ko sonce postane vroče, boste imeli pomoč.‹« Poslanci so prišli in to pokazali možem iz Jabéša in bili so veseli.',
        10: 'Zato so možje iz Jabéša rekli: »Jutri bomo prišli ven k vam in z nami boste lahko storili vse, kar se vam zdi dobro.«',
        11: 'Naslednjega dne je bilo to tako, da je Savel ljudstvo razvrstil v tri skupine in prišli so v sredo vojske ob jutranji straži in usmrtili Amónce do dnevne vročine. Pripetilo se je, da so bili tisti, ki so preostali, razkropljeni, tako da niti dva izmed njih nista ostala skupaj.',
        12: 'Ljudstvo je reklo Samuelu: »Kdo je tisti, ki je rekel: ›Ali bo Savel kraljeval nad nami?‹ Privedite može, da jih lahko usmrtimo.«',
        13: 'Savel je rekel: »Danes ne bo usmrčen noben mož, kajti danes je Gospod izvêdel rešitev duš v Izraelu.«',
        14: 'Potem je Samuel rekel ljudstvu: »Pridite in pojdimo v Gilgál in tam obnovimo kraljestvo.«',
        15: 'Vse ljudstvo je odšlo v Gilgál in tam, v Gilgálu, so postavili Savla za kralja pred Gospodom in tam so žrtvovali žrtvovanje mirovnih daritev pred Gospodom in tam so se Savel in vsi Izraelovi možje silno veselili.',
    },
    12: {
        1: 'Samuel je rekel vsemu Izraelu: »Glejte, prisluhnil sem vašemu glasu v vsem, kar ste mi rekli in postavil sem kralja nad vami.',
        2: 'In sedaj glejte, kralj hodi pred vami. Jaz pa sem starec in sivolas in glejte, moja sinova sta z vami. Hodil sem pred vami od svojega otroštva, do tega dne.',
        3: 'Glejte, tukaj sem. Pričujte zoper mene pred Gospodom in pred njegovim maziljencem. Čigavega vola sem vzel? Ali čigavega osla sem vzel? Ali sem koga ogoljufal? Koga sem zatiral? Ali iz čigave roke sem sprejel kakršnokoli podkupnino, da bi mi s tem zaslepil oči? In povrnil vam bom.«',
        4: 'Rekli so: »Nisi nas ogoljufal niti nas nisi zatiral niti nisi vzel karkoli iz roke kateregakoli moža.«',
        5: 'Rekel jim je: » Gospod je priča zoper vas in njegov maziljenec je priča ta dan, da v moji roki niste našli ničesar.« Odgovorili so: » On je priča.«',
        6: 'Samuel je ljudstvu rekel: » Gospod je ta, ki je določil Mojzesa in Arona in ki je vaše očete privedel gor iz egiptovske dežele.',
        7: 'Zdaj torej mirno stojte, da se bom lahko pravdal z vami pred Gospodom o vseh pravičnih dejanjih Gospoda, ki jih je storil vam in vašim očetom.',
        8: 'Ko je Jakob prišel v Egipt in so vaši očetje klicali h Gospodu, potem jim je Gospod poslal Mojzesa in Arona, ki sta vaše očete privedla ven iz Egipta in jim dala prebivati na tem kraju.',
        9: 'Ko pa so pozabili Gospoda, svojega Boga, jih je prodal v roko Siserája, poveljnika Hacórjeve vojske in v roko Filistejcev in v roko moábskega kralja in so se borili zoper njih.',
        10: 'Klicali so h Gospodu in rekli: ›Grešili smo, ker smo zapustili Gospoda in smo služili Báalom in Astarti. Toda sedaj nas osvobodi iz roke naših sovražnikov in mi ti bomo služili.‹',
        11: 'Gospod je poslal Jerubáala, Bedána, Jefteja in Samuela in vas osvobodil iz roke vaših sovražnikov na vsaki strani in vi ste varno prebivali.',
        12: 'Ko pa ste videli, da je proti vam prišel Naháš, kralj Amónovih otrok, ste mi rekli: ›Ne, temveč bo kralj kraljeval nad nami.‹ Ko je bil Gospod, vaš Bog, vaš kralj.',
        13: 'Zdaj torej glejte kralja, ki ste ga izbrali in ki ste si ga želeli! In glejte, Gospod je postavil kralja nad vami.',
        14: 'Če se boste bali Gospoda in mu služili in ubogali njegov glas in se ne boste uprli zoper Gospodovo zapoved, potem boste tako vi kot vaš kralj, ki kraljuje nad vami, še naprej sledili Gospodu, svojemu Bogu.',
        15: 'Toda če ne boste ubogali glasu Gospoda, temveč se boste uprli zoper Gospodovo zapoved, potem bo Gospodova roka zoper vas, kakor je bila zoper vaše očete.',
        16: 'Zdaj torej stojte in vidite to veliko stvar, ki jo bo Gospod storil pred vašimi očmi.',
        17: 'Mar ni danes pšenična žetev? Klical bom h Gospodu in poslal bo grmenje in dež, da boste lahko zaznali in videli, da je vaša zlobnost velika, ki ste jo storili v Gospodovih očeh, v tem, da ste si zahtevali kralja.«',
        18: 'Tako je Samuel zaklical h Gospodu in Gospod je ta dan poslal grmenje in dež, in vse ljudstvo se je silno balo Gospoda in Samuela.',
        19: 'Vse ljudstvo je reklo Samuelu: »Moli za svoje služabnike h Gospodu, svojemu Bogu, da ne umremo, kajti vsem svojim grehom smo dodali to zlo, da smo si zahtevali kralja.«',
        20: 'Samuel je ljudstvu rekel: »Ne bojte se. Storili ste vso to zlobnost, vendar se ne obrnite stran od sledenja Gospodu, temveč z vsem svojim srcem služite Gospodu',
        21: 'in ne obrnite se stran, kajti potem bi šli za praznimi stvarmi, ki ne morejo koristiti niti osvoboditi, kajti prazne so.',
        22: 'Kajti Gospod ne bo zapustil svojega ljudstva zaradi svojega veličastnega imena, ker je Gospodu ugajalo, da vas naredi za svoje ljudstvo.',
        23: 'Poleg tega, kar se mene tiče, Bog ne daj, da bi grešil zoper Gospoda v [tem], da bi prenehal moliti za vas, temveč vas bom učil dobro in pravilno pot.',
        24: 'Samo bojte se Gospoda in mu služite v resnici, z vsem svojim srcem, kajti preudarite kako velike stvari je storil za vas.',
        25: 'Toda če boste še vedno počeli zlobno, boste použiti, tako vi kakor vaš kralj.«',
    },
    13: {
        1: 'Savel je kraljeval eno leto in ko je nad Izraelom kraljeval dve leti,',
        2: 'si je Savel izbral tri tisoč mož iz Izraela, od katerih jih je bilo dva tisoč s Savlom v Mihmášu in na gori Betel, tisoč pa jih je bilo z Jonatanom v Benjaminovi Gíbei, preostanek ljudstva pa je poslal vsakega moža k svojemu šotoru.',
        3: 'Jonatan je udaril garnizijo Filistejcev, ki je bila v Gebi in Filistejci so slišali o tem. Savel pa je zatrobil na šofar po vsej deželi, rekoč: »Naj Hebrejci slišijo.«',
        4: 'Ves Izrael je slišal govoriti, da je Savel udaril garnizijo Filistejcev in da je bil tudi Izrael v ogabnost Filistejcem. In ljudstvo je bilo sklicano skupaj za Savlom v Gilgál.',
        5: 'Filistejci so se zbrali skupaj, da se bojujejo z Izraelom, trideset tisoč bojnih vozov, šest tisoč konjenikov in ljudstva v obilju, kakor je peska na morski obali. Prišli so gor in se utaborili v Mihmášu, vzhodno od Bet Avena.',
        6: 'Ko so možje iz Izraela videli, da so bili v škripcu (kajti ljudje so bili zelo stiskani), potem so se ljudje skrili v votlinah, v goščavah, v skalah, na visokih krajih in v jamah.',
        7: 'Nekateri izmed Hebrejcev so odšli preko Jordana k deželi Gada in Gileáda. Glede Savla, on je bil še vedno v Gilgálu in vse ljudstvo mu je trepetajoč sledilo.',
        8: 'Zadrževal se je sedem dni, glede na določeni čas, ki ga je Samuel določil. Toda Samuel ni prišel v Gilgál, ljudstvo pa je bilo razkropljeno od njega.',
        9: 'Savel je rekel: »Prinesite sèm k meni žgalno daritev in mirovne daritve.« In daroval je žgalno daritev.',
        10: 'Pripetilo se je, da takoj, ko je končal daritev žgalne daritve, glej, je prišel Samuel. Savel je odšel ven, da ga sreča, da bi ga lahko pozdravil.',
        11: 'Samuel je rekel: »Kaj si storil?« Savel je rekel: »Ker sem videl, da je bilo ljudstvo razkropljeno proč od mene in da ti nisi prišel v določenih dneh in da so se Filistejci zbrali skupaj pri Mihmášu,',
        12: 'sem zato rekel: ›Filistejci bodo sedaj prišli nadme dol v Gilgál, jaz pa nisem naredil ponižne prošnje h Gospodu.‹ Zato sem se prisilil in daroval žgalno daritev.«',
        13: 'Samuel je rekel Savlu: »Storil si nespametno. Nisi se držal zapovedi Gospoda, svojega Boga, ki ti jo je zapovedal, kajti sedaj bi Gospod na veke utrdil tvoje kraljestvo nad Izraelom.',
        14: 'Toda sedaj tvoje kraljestvo ne bo trajalo. Gospod si je poiskal moža po svojem lastnem srcu in Gospod mu je zapovedal, da bi bil poveljnik nad njegovim ljudstvom, ker se ti nisi držal tega, kar ti je Gospod zapovedal.«',
        15: 'Samuel je vstal in se iz Gilgála povzpel v Benjaminovo Gíbeo. Savel je preštel ljudstvo, ki je bilo prisotno z njim, približno šeststo mož.',
        16: 'Savel, njegov sin Jonatan in ljudstvo, ki je bilo prisotno z njima, je ostalo v Benjaminovi Gíbei, toda Filistejci so taborili v Mihmášu.',
        17: 'Iz tabora Filistejcev so prišli plenilci v treh skupinah. Ena skupina se je obrnila k poti, ki vodi v Ofro, v deželo Šuál.',
        18: 'Druga skupina se je obrnila k poti do Bet Horóna. [Še] druga skupina se je obrnila k poti meje, ki je obrnjena k dolini Cebojím, proti divjini.',
        19: 'Torej po vsej Izraelovi deželi ni bilo najti kovača, kajti Filistejci so rekli: »Da si ne bi Hebrejci naredili mečev ali sulic,«',
        20: 'temveč so vsi Izraelci hodili dol k Filistejcem, da si nabrusijo vsak mož svoj nož pri plugu, svoje črtalo pluga, svojo sekiro in svojo motiko.',
        21: '§ Vendar so imeli pilo za motike, za črtala plugov, za vile, za sekire in da naostrijo palice z bodico.',
        22: 'Tako se je na dan bitke pripetilo, da ni bilo najti niti meča niti sulice v roki kateregakoli izmed ljudstva, ki so bili s Savlom in Jonatanom. Toda najti ju je bilo pri Savlu in njegovem sinu Jonatanu.',
        23: 'Garnizija Filistejcev je odšla ven k prehodu Mihmáša.',
    },
    14: {
        1: 'Pripetilo se je torej na dan, ko je Savlov sin Jonatan rekel mladeniču, ki je nosil njegovo bojno opremo: »Pridi in pojdiva preko, k filistejski garniziji, ki je na drugi strani.« Toda ni povedal svojemu očetu.',
        2: 'Savel je sedel na najbolj oddaljenem delu Gíbee, pod granatovcem, ki je v Migrónu in ljudstva, ki je bilo z njim, je bilo približno šeststo mož.',
        3: 'Ahíja, sin Ahitúba, Ikabódov brat, sinú Pinhása, sinú Élija, Gospodovega duhovnika v Šilu, je nosil efód. Ljudstvo pa ni vedelo, da je Jonatan odšel.',
        4: 'Med prehodi, ob katerih je Jonatan iskal, da bi šel preko k filistejski garniziji, je bila ostra skala na eni strani in ostra skala na drugi strani. Ime ene je bilo Bocéc, ime druge pa Sene.',
        5: 'Sprednji del ene je bil obrnjen proti severu, nasproti Mihmášu in druge proti jugu, nasproti Gíbei.',
        6: 'Jonatan je rekel mladeniču, ki je nosil njegovo bojno opremo: »Pridi in pojdiva preko, h garniziji teh neobrezancev. Morda bo Gospod delal za naju, kajti ni omejitve Gospodu, da reši po mnogih ali po peščici.«',
        7: 'Njegov nosilec bojne opreme mu je rekel: »Stori vse, kar je v tvojem srcu. Obrni se, glej, jaz sem s teboj glede na tvoje srce.«',
        8: 'Potem je Jonatan rekel: »Glej, šla bova preko, k tem možem in se jim bova odkrila.',
        9: 'Če nama rečejo: ›Ostanita, dokler ne pridemo do vaju,‹ potem bova mirno stala na svojem kraju in ne bova šla gor k njim.',
        10: 'Toda če rečejo tako: ›Pridita gor k nam,‹ potem bova šla gor, kajti Gospod jih je izročil v najino roko in to nama bo za znamenje.«',
        11: 'Oba izmed njiju sta se odkrila garniziji Filistejcev. Filistejci so rekli: »Poglejte, Hebrejci prihajajo iz lukenj, kamor so se skrili.«',
        12: 'Možje iz garnizije so Jonatanu in njegovemu nosilcu bojne opreme odgovorili ter rekli: »Pridita gor k nam in pokazali vama bomo stvar.« Jonatan je rekel svojemu nosilcu bojne opreme: »Pridi gor za menoj, kajti Gospod jih je izročil v Izraelovo roko.«',
        13: 'Jonatan je plezal gor po svojih rokah in po svojih stopalih in njegov nosilec bojne opreme za njim in padali so pred Jonatanom. Njegov nosilec bojne opreme pa jih je pobijal za njim.',
        14: 'Ta prvi pokol, ki sta ga naredila Jonatan in njegov nosilec bojne opreme, je zajel okrog dvajset mož, kakor bi bilo znotraj pol orala dežele, ki bi jo lahko preoral jarem volov.',
        15: 'V vojski na polju in med vsem ljudstvom je bilo trepetanje. Garnizija in plenilci, tudi oni so trepetali in zemlja se je tresla. Tako je bilo zelo veliko trepetanje.',
        16: 'Savlovi stražarji v Benjaminovi Gíbei so pogledali in glej, množica se je razblinila in nadaljevali so s podiranjem drug drugega.',
        17: 'Potem je Savel rekel ljudstvu, ki je bilo z njim: »Preštejte torej in poglejte, kdo je odšel od nas.« Ko so prešteli, glej, Jonatan in njegov nosilec bojne opreme nista bila tam.',
        18: 'Savel je rekel Ahíju: »Prinesi sèm Božjo skrinjo.« Kajti Božja skrinja je bila ob tistem času z Izraelovimi otroki.',
        19: 'Pripetilo se je, medtem ko je Savel govoril z duhovnikom, da se je hrup, ki je bil v vojski Filistejcev, nadaljeval in naraščal in Savel je rekel duhovniku: »Umakni svojo roko.«',
        20: 'Savel ter vse ljudstvo, ki je bilo z njim, so se zbrali skupaj in prišli k bitki. Glej, meč vsakega moža je bil proti njegovemu tovarišu in tam je bila zelo velika zmeda.',
        21: 'Pa tudi Hebrejci, ki so bili pred tem časom s Filistejci, ki so iz okoliške dežele odšli z njimi gor v tabor, celo ti so se prav tako obrnili, da bi bili z Izraelci, ki so bili s Savlom in Jonatanom.',
        22: 'Podobno so tudi vsi Izraelovi možje, ki so se skrili na gori Efrájim, ko so slišali, da so Filistejci zbežali, celo oni so sledili tik za njimi v bitko.',
        23: 'Tako je Gospod tisti dan rešil Izraela. Bitka je prešla preko k Bet Avenu.',
        24: 'Izraelovi možje so bili ta dan užaloščeni, kajti Savel je ljudstvo zaprisegel, rekoč: »Preklet naj bo mož, ki poje kakršnokoli hrano do večera, da bom lahko maščevan na svojih sovražnikih.« Tako nihče izmed ljudstva ni pokusil nobene hrane.',
        25: 'Vsi tisti iz dežele so prišli do gozda in tam je bil na tleh med.',
        26: 'Ko je ljudstvo prišlo v gozd, glej, je kapljal med, toda noben mož ni iztegnil svoje roke k svojim ustom, kajti ljudstvo se je balo prisege.',
        27: 'Toda Jonatan ni slišal, ko je njegov oče ljudstvo obremenil s prisego. Zato je iztegnil konec palice, ki je bila v njegovi roki in jo omočil v satovju in svojo roko nesel k ustom in njegove oči so bile razsvetljene.',
        28: 'Potem je odgovoril eden izmed ljudstva in rekel: »Tvoj oče je s prisego strogo obremenil ljudstvo, rekoč: ›Preklet bodi človek, ki danes poje kakršnokoli hrano.‹« In ljudstvo je bilo slabotno.',
        29: 'Potem je Jonatan rekel: »Moj oče je vznemiril deželo. Poglej, prosim te, kako so bile moje oči razsvetljene, ker sem okusil malo od tega medu.',
        30: 'Kako mnogo bolj, če bi morda ljudstvo danes prosto jedlo od plena svojih sovražnikov, ki so ga našli? Kajti ali ne bi bil sedaj veliko večji pokol med Filistejci?«',
        31: 'Ta dan so udarili Filistejce od Mihmáša do Ajalóna, ljudstvo pa je bilo zelo slabotno.',
        32: 'In ljudstvo se je vrglo na plen in vzelo ovce, vole in teleta in zaklali so jih na tleh. Ljudstvo jih je jedlo s krvjo.',
        33: 'Potem so povedali Savlu, rekoč: »Glej, ljudstvo greši zoper Gospoda v tem, da jedo s krvjo.« Rekel je: »Pregrešili ste se. Zavalite k meni ta dan velik kamen.«',
        34: 'Savel je rekel: »Razpršite se med ljudstvo in jim recite: ›Privedite mi sèm vsak človek svojega vola in vsak človek svojo ovco in zakoljite jih tukaj in jejte in ne grešite zoper Gospoda, v tem, da bi jedli s krvjo.‹« Vse ljudstvo je to noč privedlo, vsak človek svojega vola s seboj in so jih tam zaklali.',
        35: 'Savel je zgradil oltar Gospodu. Ta isti je bil prvi oltar, ki ga je zgradil Gospodu.',
        36: 'Savel je rekel: »Pojdimo ponoči dol za Filistejci in jih plenimo do jutranje svetlobe in ne pustimo nobenega moža od njih.« Rekli so: »Stôri, karkoli se ti zdi dobro.« Potem je rekel duhovniku: »Približajmo se sèm k Bogu.«',
        37: 'Savel je vprašal za nasvet od Boga: »Ali naj grem dol za Filistejci? Ali jih boš izročil v Izraelovo roko?« Toda tisti dan mu ni odgovoril.',
        38: 'Savel je rekel: »Približajte se sèm, vsi vodje ljudstva in vedite in poglejte, v čem je bil ta greh ta dan.',
        39: 'Kajti kakor živi Gospod, ki rešuje Izrael, čeprav bi bil ta na mojem sinu Jonatanu, bo on zagotovo umrl.« Toda tam ni bilo moža izmed ljudstva, da bi mu odgovoril.',
        40: 'Potem je vsemu Izraelu rekel: »Vi bodite na eni strani, jaz in moj sin Jonatan pa bova na drugi strani.« Ljudstvo je Savlu reklo: »Stori, kar se ti zdi dobro.«',
        41: 'Zato je Savel rekel Gospodu, Izraelovemu Bogu: »Daj popoln žreb.« Zajeta sta bila Savel in Jonatan, toda ljudstvo je bilo izločeno.',
        42: 'Savel je rekel: »Vrzite žrebe med menoj in mojim sinom Jonatanom.« In izbran je bil Jonatan.',
        43: 'Potem je Savel rekel Jonatanu: »Povej mi kaj si storil.« Jonatan mu je povedal in rekel: »Samo pokusil sem malo medu s koncem palice, ki je bila v moji roki in glej, moram umreti.«',
        44: 'Savel je odgovoril: »Bog stori tako in še več, kajti zagotovo boš umrl, Jonatan.«',
        45: 'Ljudstvo pa je reklo Savlu: »Ali naj Jonatan umre, ki je izvršil to veliko rešitev duš v Izraelu? Bog ne daj. Kakor Gospod živi, ne bo niti en las iz njegove glave padel na tla, kajti ta dan je delal z Bogom.« Tako je ljudstvo rešilo Jonatana, da ni umrl.',
        46: 'Potem je Savel odšel gor od sledenja Filistejcem in Filistejci so odšli k svojemu lastnemu kraju.',
        47: 'Tako je Savel vzel kraljestvo nad Izraelom in se boril zoper vse svoje sovražnike na vsaki strani, zoper Moáb, zoper Amónove otroke, zoper Edóm, zoper kralje Cobe in zoper Filistejce in h komurkoli se je obrnil, jim je povzročal skrbi.',
        48: 'Zbral je vojsko, udaril Amalečane in Izraela osvobodil iz rok tistih, ki so jih plenili.',
        49: 'Torej Savlovi sinovi so bili Jonatan, Jišví in Malkišúa. Imena njegovih dveh hčera sta bili: ime prvorojene Merába in ime mlajše Mihála.',
        50: 'Ime Savlove žene je bilo Ahinóam, Ahimáacova hči. Ime poveljnika njegove vojske je bilo Abnêr, sin Savlovega strica Nera.',
        51: '§ Kiš je bil Savlov oče in Abnêrjev oče Ner je bil Abiélov sin.',
        52: 'In tam je bila silna vojna zoper Filistejce vse Savlove dni in ko je Savel zagledal kateregakoli močnega moža ali kateregakoli hrabrega moža, ga je vzel k sebi.',
    },
    15: {
        1: 'Samuel je tudi rekel Savlu: » Gospod me je poslal, da te mazilim, da bi bil kralj nad njegovim ljudstvom, nad Izraelom. Sedaj torej prisluhni glasu Gospodovih besed.',
        2: 'Tako govori Gospod nad bojevniki: ›Spomnim se tega, kar je Amálek storil Izraelu, kako je prežal nanj na poti, ko je prišel gor iz Egipta.',
        3: 'Sedaj pojdi in udari Amáleka in popolnoma uniči vse, kar imajo in ne prizanesi jim, temveč ubij tako moškega kakor žensko, otroka in dojenčka, vola in ovco, kamelo in osla.‹«',
        4: 'Savel je ljudstvo zbral skupaj in jih preštel v Telaímu, dvesto tisoč pešcev in deset tisoč mož iz Juda.',
        5: 'Savel je prišel do mesta Amálečanov in prežal v dolini.',
        6: 'Savel je Kenéjcem rekel: »Pojdite, odidite dol izmed Amálečanov, da vas ne bi uničil z njimi, kajti izkazali ste prijaznost vsem Izraelovim otrokom, ko so prišli gor iz Egipta.« Tako so Kenéjci odšli izmed Amalečanov.',
        7: 'Savel je udaril Amalečane od Havíle, dokler ne prideš do Šura, ki je nasproti Egiptu.',
        8: 'Agága, kralja Amalečanov, je zajel živega in z ostrino meča popolnoma uničil vse ljudstvo.',
        9: 'Toda Savel in ljudstvo je prizaneslo Agágu in najboljšemu od ovc, od volov, od pitancev in jagnjet in vsega, kar je bilo dobro in niso jih želeli popolnoma uničiti. Toda vsako stvar, ki je bila ničvredna in zavrnjena, to so popolnoma uničili.',
        10: 'Potem je prišla Gospodova beseda Samuelu, rekoč:',
        11: '»To me je pokesalo, da sem postavil Savla, da bi bil kralj, kajti obrnil se je nazaj od sledenja meni in ni izvršil mojih zapovedi.« To je užalostilo Samuela in ta je vso noč klical h Gospodu.',
        12: 'Ko je Samuel zgodaj vstal, da bi zjutraj srečal Savla, je bilo Samuelu povedano, rekoč: »Savel je prišel v Karmel in glej, postavil si je kraj in potem je šel naokrog, šel naprej in odšel dol do Gilgála.«',
        13: 'Samuel je prišel k Savlu in Savel mu je rekel: »Blagoslovljen bodi od Gospoda. Izpolnil sem Gospodovo zapoved.«',
        14: 'Samuel pa je rekel: »Kaj potem pomeni to blejanje ovc v mojih ušesih in mukanje volov, ki ga slišim?«',
        15: 'Savel je rekel: »Privedli so jih od Amalečanov, kajti ljudstvo je prizaneslo najboljšim izmed ovc in izmed volov, da žrtvujejo Gospodu, tvojemu Bogu, preostalo pa smo popolnoma uničili.«',
        16: 'Potem je Samuel rekel Savlu: »Ostani in povedal ti bom kaj mi je to noč povedal Gospod.« In rekel mu je: »Povej.«',
        17: 'Samuel je rekel: »Ko si bil majhen v svojem lastnem pogledu, ali nisi bil narejen za poglavarja Izraelovim rodovom in te je Gospod mazilil za kralja nad Izraelom?',
        18: 'Gospod te je poslal na pot in rekel: ›Pojdi in popolnoma uniči grešnike Amalečane in se bori proti njim, dokler ne bodo použiti.‹',
        19: 'Zakaj potem nisi ubogal Gospodovega glasu, temveč si se vrgel na plen in storil zlo v Gospodovih očeh?«',
        20: 'Savel je rekel Samuelu: »Da, ubogal sem Gospodov glas in sem šel na pot, na katero me je poslal Gospod in privedel sem Agága, kralja Amalečanov in popolnoma sem uničil Amálečane.',
        21: 'Toda ljudstvo je vzelo od plena, ovce in vole, glavne izmed stvari, ki naj bi bile popolnoma uničene, da žrtvujejo Gospodu, tvojemu Bogu v Gilgálu.«',
        22: 'Samuel je rekel: »Ali ima Gospod tako veliko zadovoljstvo v žgalnih daritvah in klavnih daritvah, kot v ubogljivosti Gospodovemu glasu? Glej, ubogati je bolje kot klavna daritev in poslušati [bolje] kot tolšča ovnov.',
        23: 'Kajti upor je kakor greh čaranja in trmoglavost je kakor krivičnost in malikovanje. Ker si zavrnil Gospodovo besedo, je tudi on zavrnil tebe, da bi bil kralj.«',
        24: 'Savel je rekel Samuelu: »Grešil sem, kajti prekršil sem Gospodovo zapoved in tvoje besede, ker sem se bal ljudstva in ubogal njihov glas.',
        25: 'Zdaj torej, prosim te, odpusti moj greh in se ponovno obrni z menoj, da lahko obožujem Gospoda.«',
        26: 'Samuel pa je rekel Savlu: »Ne bom se vrnil s teboj, kajti zavrnil si Gospodovo besedo in Gospod je zavrnil tebe, da bi bil kralj nad Izraelom.«',
        27: 'Medtem ko se je Samuel obrnil naokoli, da gre proč, je zgrabil krajec njegovega plašča in ga odtrgal.',
        28: 'Samuel pa mu je rekel: » Gospod je ta dan odtrgal Izraelovo kraljestvo od tebe in ga izročil tvojemu bližnjemu, ki je boljši kakor ti.',
        29: 'Tudi Močni Izraelov ne bo lagal niti se kesal, kajti on ni človek, da bi se kesal.«',
        30: 'Potem je rekel: »Grešil sem. Vendar me sedaj počasti, prosim te, pred starešinami mojega ljudstva in pred Izraelom in se ponovno obrni z menoj, da bom lahko oboževal Gospoda, tvojega Boga.«',
        31: 'Tako se je Samuel ponovno obrnil za Savlom, in Savel je oboževal Gospoda.',
        32: 'Potem je Samuel rekel: »Privedite sèm k meni Agága, kralja Amalečanov.« Agág je prefinjeno prišel k njemu. In Agág je rekel: »Zagotovo je grenkoba smrti minila.«',
        33: 'Samuel je rekel: »Kakor je tvoj meč naredil ženske brez otrok, tako bo tvoja mati brez otroka med ženskami.« In Samuel je Agága razsekal na koščke pred Gospodom v Gilgálu.',
        34: 'Potem je Samuel odšel v Ramo, Savel pa je odšel gor, do svoje hiše, v Savlovo Gíbeo.',
        35: 'Samuel ni več prišel, da bi videl Savla, do dneva svoje smrti, vendar je Samuel žaloval za Savlom. In Gospod se je pokesal, da je Savla postavil [za] kralja nad Izraelom.',
    },
    16: {
        1: 'Gospod je rekel Samuelu: »Doklej boš žaloval za Savlom, glede na to, da sem ga zavrnil od kraljevanja nad Izraelom? Napolni svoj rog z oljem in pojdi, poslal te bom k Betlehemcu Jeseju, kajti med njegovimi sinovi sem si priskrbel kralja.«',
        2: 'Samuel je rekel: »Kako lahko grem? Če Savel to sliši, me bo ubil.« Gospod je rekel: »Vzemi s seboj telico in reci: ›Prišel sem, da žrtvujem Gospodu.‹',
        3: 'H klavni daritvi pokliči Jeseja, jaz pa ti bom pokazal kaj boš storil in mazilil mi boš tistega, ki ti ga imenujem.«',
        4: 'Samuel je storil to, kar je Gospod govoril in prišel v Betlehem. Starešine mesta pa so trepetali ob njegovem prihodu in rekli: »Ali prihajaš miroljubno?«',
        5: 'Rekel je: »Miroljubno. Prišel sem, da darujem Gospodu. Posvetite se in pridite z menoj h klavni daritvi.« In Jeseja in njegove sinove je posvetil ter jih poklical k daritvi.',
        6: 'Pripetilo se je, ko so prišli, da je pogledal na Eliába in rekel: »Zagotovo je Gospodov maziljenec pred njim.«',
        7: 'Toda Gospod je rekel Samuelu: »Ne glej na njegovo obličje ali na višino njegove postave, ker sem ga odklonil, kajti GOSPOD ne vidi, kakor vidi človek; kajti človek gleda na zunanji videz, toda Gospod gleda na srce.«',
        8: 'Potem je Jese poklical Abinadába in ga primoral, da gre pred Samuela. In ta je rekel: »Niti tega Gospod ni izbral.«',
        9: 'Potem je Jese primoral Šamája, da gre mimo. Rekel je: »Niti Gospod ni izbral tega.«',
        10: 'Ponovno, Jese je primoral sedem svojih sinov, da gredo mimo pred Samuelom. Samuel je rekel Jeseju: » Gospod ni izbral teh.«',
        11: 'Samuel je rekel Jeseju: »Ali so tukaj vsi tvoji otroci?« Rekel je: »Ostaja še najmlajši in glej, on varuje ovce.« Samuel je rekel Jeseju: »Pošlji in privedi ga, kajti ne bomo sedli dol, dokler on ne pride sèm.«',
        12: 'Poslal je in ga privedel noter. Torej bil je rdečkast in hkrati lepega obličja in čeden na pogled. In Gospod je rekel: »Vstani, mazili ga, kajti to je on.«',
        13: 'Potem je Samuel vzel rog olja in ga mazilil v sredi njegovih bratov. Gospodov Duh je prišel na Davida od tega dne dalje. Tako je Samuel vstal in odšel v Ramo.',
        14: 'Vendar pa je Gospodov Duh odšel od Savla in zli duh od Gospoda ga je nadlegoval.',
        15: 'Savlovi služabniki so mu rekli: »Glej torej, nadleguje te zli duh od Boga.',
        16: 'Naj naš gospod sedaj zapove svojim služabnikom, ki so pred teboj, da poiščejo človeka, ki je spreten igralec na harfo. Zgodilo se bo, ko bo nad teboj zli duh od Boga, da bo igral s svojo roko, tebi pa bo dobro.«',
        17: 'Savel je svojim služabnikom rekel: »Priskrbite mi torej človeka, ki lahko dobro igra in ga privedite k meni.«',
        18: 'Potem je eden izmed služabnikov odgovoril in rekel: »Glej, videl sem sina Betlehemca Jeseja, ki je spreten v igranju, močan, hraber mož, bojevnik, razsoden v zadevah in ljubke osebnosti in Gospod je z njim.«',
        19: 'Zato je Savel poslal poslance k Jeseju in rekel: »Pošlji mi svojega sina Davida, ki je z ovcami.«',
        20: 'Jese je vzel osla, obloženega s kruhom, vinski meh, kozlička in jih po svojem sinu Davidu poslal k Savlu.',
        21: 'David je prišel k Savlu in stal pred njim in on ga je silno vzljubil in postal je njegov nosilec bojne opreme.',
        22: 'Savel je poslal k Jeseju, rekoč: »Pusti Davida, prosim te, stati pred menoj, kajti našel je naklonjenost v mojem pogledu.«',
        23: 'Pripetilo se je, ko je bil zli duh od Boga nad Savlom, da je David vzel harfo in igral s svojo roko. Tako je bil Savel osvežen in bilo mu je dobro in zli duh je odšel od njega.',
    },
    17: {
        1: 'Torej Filistejci so zbrali skupaj svoje vojske za boj in zbrani so bili skupaj pri Sohóju, ki pripada Judu in se utaborili med Sohójem in Azéko, v Efes Damímu.',
        2: 'Savel in Izraelovi možje so bili zbrani skupaj in se utaborili poleg doline Elá in se postrojili v boj zoper Filistejce.',
        3: 'Filistejci so stali na gori na eni strani, Izrael pa je stal na gori na drugi strani in med njimi je bila dolina.',
        4: 'Iz tabora Filistejcev je prišel šampion iz Gata, po imenu Goljat, katerega višina je bila šest komolcev in pedenj.',
        5: 'Na svoji glavi je imel čelado iz brona in oborožen je bil z verižnim plaščem. Teža plašča je bila pet tisoč šeklov brona',
        6: 'Na svojih nogah je imel bronaste golenice in okrogel ščit iz brona med svojimi rameni.',
        7: 'Palica njegove sulice je bila podobna tkalčevemu brunu in vrh njegove sulice je tehtal šeststo šeklov železa in nekdo, ki je nosil ščit, je šel pred njim.',
        8: 'Stal je in klical Izraelovim vojskam ter jim rekel: »Zakaj ste prišli ven, da se postrojite za boj? Mar nisem jaz Filistejec, vi pa Savlovi služabniki? Izberite zase moža in naj pride dol k meni.',
        9: 'Če se je zmožen bojevati z menoj in me ubiti, potem bomo mi vaši služabniki, toda če prevladam zoper njega in ga ubijem, potem boste vi naši služabniki in nam služili.«',
        10: 'Filistejec je rekel: »Danes izzivam Izraelove vojske. Dajte mi človeka, da se lahko skupaj bojujeva.«',
        11: 'Ko so Savel in ves Izrael slišali te Filistejčeve besede, so bili zaprepadeni in silno prestrašeni.',
        12: 'Torej David je bil sin tega Efratejca iz Judovega Betlehema, katerega ime je bilo Jese. Ta je imel osem sinov. V Savlovih dneh je mož odšel med može za starca.',
        13: 'Trije najstarejši Jesejevi sinovi so odšli in Savlu sledili v bitko. Imena njegovih treh sinov, ki so šli v bitko, so bila Eliáb, prvorojenec in poleg njega Abinadáb in tretji Šamá.',
        14: 'David je bil najmlajši in trije starejši so sledili Savlu.',
        15: 'Toda David je šel in se vrnil od Savla, da pri Betlehemu pase ovce svojega očeta.',
        16: 'Filistejec se je približal zjutraj in zvečer in se nastavljal štirideset dni.',
        17: 'Jese je svojemu sinu Davidu rekel: »Vzemi sedaj za svoje brate škaf tega praženega zrnja in teh deset hlebov ter steci v tabor k svojim bratom',
        18: 'in teh deset sirov odnesi k poveljniku njihove tisočnije in poglej, kako se imajo tvoji bratje in vzemi njihovo jamstvo.«',
        19: 'Torej Savel in oni in vsi Izraelovi možje so bili v dolini Elá, boreč se s Filistejci.',
        20: 'David je vstal zgodaj zjutraj in pustil ovce s čuvajem in vzel ter odšel, kakor mu je Jese zapovedal. Prišel je k okopu, medtem ko je šla vojska naprej v boj in zavpila za boj.',
        21: 'Kajti Izrael in Filistejci so se postrojili v bitko, vojska zoper vojsko.',
        22: 'David je pustil svoj voz v roki čuvaja voza, stekel v vojsko, prišel in pozdravil svoje brate.',
        23: 'Medtem ko je govoril z njimi, glej, je prišel šampion, Filistejec iz Gata, po imenu Goljat, iz vojske Filistejcev in govoril glede na te iste besede in David jih je slišal.',
        24: 'Ko so vsi Izraelovi možje videli moža, so zbežali pred njim in bili so boleče prestrašeni.',
        25: 'Možje iz Izraela so rekli: »Ali ste videli tega moža, ki je prišel gor? Zagotovo je prišel gor, da Izraela izpostavi sramotenju. Zgodilo se bo, da bo moža, ki ga ubije, kralj obogatil z velikimi bogastvi in dal mu bo svojo hčer in osvobodil hišo njegovega očeta v Izraelu.«',
        26: 'David je spregovoril možem, ki so stali poleg njega, rekoč: »Kaj bo storjeno možu, ki ubije tega Filistejca in odvzame grajo od Izraela? Kajti kdo je ta neobrezani Filistejec, da bi izpostavljal sramotenju vojske živega Boga?«',
        27: 'Ljudstvo mu je odgovorilo na ta način, rekoč: »Tako bo storjeno možu, ki ga ubije.«',
        28: 'Njegov najstarejši brat Eliáb pa je slišal, ko je govoril možem. Eliábova jeza je bila vžgana zoper Davida in rekel je: »Zakaj si prišel sèm dol? In s kom si pustil tistih nekaj ovc v divjini? Poznam tvojo ošabnost in porednost tvojega srca, kajti prišel si dol, da bi lahko videl bitko.«',
        29: 'David je rekel: »Kaj sem torej storil? Mar ni tam razlog?«',
        30: 'Od njega se je obrnil k drugemu in mu govoril na isti način, ljudstvo pa mu je ponovno odgovorilo po prejšnjem načinu.',
        31: 'Ko so bile slišane besede, ki jih je govoril David, so jih ponovili pred Savlom. In ta je poslal ponj.',
        32: 'David je rekel Savlu: »Naj srce nobenega človeka ne upade zaradi njega. Tvoj služabnik bo šel in se boril s tem Filistejcem.«',
        33: 'Savel je rekel Davidu: »Ti nisi zmožen iti zoper tega Filistejca, da se boriš z njim, kajti ti si še mladostnik, on pa je bojevnik od svoje mladosti.«',
        34: 'David je rekel Savlu: »Tvoj služabnik je pasel ovce svojega očeta in prišel je lev in medved in vzel jagnje iz tropa.',
        35: 'Odšel sem ven za njim, ga udaril in to osvobodil iz njegovih ust. Ko se je dvignil zoper mene, sem ga ujel za njegovo grivo, ga udaril in usmrtil.',
        36: 'Tvoj služabnik je usmrtil tako leva kakor medveda in ta neobrezani Filistejec bo kakor eden izmed njiju, glede na to, da je izzival vojske živega Boga.«',
        37: 'Poleg tega je David rekel: » Gospod, ki me je osvobodil iz levje šape in iz medvedje šape, on me bo osvobodil iz roke tega Filistejca.« In Savel je rekel Davidu: »Pojdi in Gospod bodi s teboj.«',
        38: 'Savel je Davida oborožil s svojo bojno opremo in mu na glavo nadel bronasto čelado. Prav tako ga je oborožil z verižnim plaščem.',
        39: 'David je opasal svoj meč na svojo bojno opremo in poskušal oditi, kajti tega ni preizkusil. David je rekel Savlu: »Ne morem iti s tem, kajti teh [stvari] nisem preizkusil.« In David jih je odložil iz sebe.',
        40: 'Vzel je svojo palico v svojo roko in si izbral pet gladkih kamnov iz potoka in jih položil v pastirsko torbo, ki jo je imel, celo v malho in njegova prača je bila v njegovi roki in približal se je Filistejcu.',
        41: 'Filistejec je prišel in se približal Davidu in mož, ki je nosil ščit, je šel pred njim.',
        42: 'Ko je Filistejec pogledal naokoli in zagledal Davida, ga je preziral, kajti bil je šele mladostnik, rdečkast in lepega obličja.',
        43: 'Filistejec je Davidu rekel: » Sem mar pes, da prihajaš k meni s palicami?« Filistejec je Davida preklel pri svojih bogovih.',
        44: 'Filistejec je rekel Davidu: »Pridi k meni in tvoje meso bom izročil perjadi neba in živalim polja.«',
        45: 'Potem je David rekel Filistejcu: »Ti prihajaš k meni z mečem, s sulico in s ščitom, toda jaz prihajam k tebi v imenu Gospoda nad bojevniki, Boga Izraelovih vojsk, ki si ga izpostavljal sramotenju.',
        46: 'Ta dan te bo Gospod izročil v mojo roko in udaril te bom in tvojo glavo vzel iz tebe in trupla vojske Filistejcev bom ta dan izročil zračni perjadi in divjim zverem zemlje, da bo vsa zemlja lahko vedela, da je Bog v Izraelu.',
        47: 'Ves ta zbor bo vedel, da Gospod ne rešuje z mečem in sulico, kajti boj je Gospodov in on vas bo izročil v naše roke.«',
        48: 'Pripetilo se je, ko je Filistejec vstal in prišel ter se približal, da sreča Davida, da je David pohitel in stekel proti vojski, da sreča Filistejca.',
        49: 'David je svojo roko položil v svojo torbo, od tam vzel kamen, ga zalučal in udaril Filistejca v njegovo čelo, da je kamen potonil v njegovo čelo in ta je padel na svoj obraz k zemlji.',
        50: 'Tako je David prevladal nad Filistejcem s pračo in s kamnom in Filistejca udaril in ubil, pa vendar v Davidovi roki ni bilo meča.',
        51: 'Zato je David stekel in obstal nad Filistejcem, vzel njegov meč, ga izvlekel iz njegove nožnice, ga ubil in z njim odsekal njegovo glavo. Ko so Filistejci videli, da je bil njihov šampion mrtev, so pobegnili.',
        52: 'Možje iz Izraela in možje iz Juda so vstali, zavpili in zasledovali Filistejce, dokler ne prideš do doline in k velikim vratom Ekróna. Ranjeni izmed Filistejcev so padali dol po poti k Šaarájimu, celo do Gata in do Ekróna.',
        53: 'Izraelovi otroci so se vrnili iz preganjanja za Filistejci in oplenili njihove šotore.',
        54: 'David je vzel glavo Filistejca in jo prinesel v Jeruzalem, toda njegovo bojno opremo je odložil v svoj šotor.',
        55: 'Ko je Savel zagledal Davida iti naprej zoper Filistejca, je rekel Abnêrju, poveljniku vojske: »Abnêr, čigav sin je ta mladostnik?« Abnêr je rekel: » Kakor živi tvoja duša, oh kralj, ne morem povedati.«',
        56: 'Kralj je rekel: »Poizvedi, čigav sin je ta najstnik.«',
        57: 'Ko se je David vrnil iz uboja Filistejca, ga je Abnêr vzel in privedel pred Savla, s Filistejčevo glavo v svoji roki.',
        58: 'Savel mu je rekel: »Čigav sin si ti, ti mladenič?« David je odgovoril: »Jaz sem sin tvojega služabnika Betlehemca Jeseja.«',
    },
    18: {
        1: 'Pripetilo se je, ko je končal pogovor s Savlom, da se je Jonatanova duša povezala z Davidovo dušo in Jonatan ga je vzljubil kakor svojo lastno dušo.',
        2: 'Savel ga je ta dan vzel in mu ni več dovolil iti domov, k hiši svojega očeta.',
        3: 'Potem sta Jonatan in David sklenila zavezo, ker ga je vzljubil kakor svojo lastno dušo.',
        4: 'Jonatan si je slekel vrhnje oblačilo, ki je bilo na njem in ga dal Davidu, in svoja oblačila, celo do svojega meča, svojega loka in svojega pasu.',
        5: '§ David je odšel ven, kamor ga je poslal Savel in se modro vedel. Savel ga je postavil nad bojevnike in sprejet je bil pred očmi vsega ljudstva in tudi pred očmi Savlovih služabnikov.',
        6: 'Pripetilo se je, medtem ko so prišli, ko se je David vrnil iz pokola Filistejca, da so prišle ženske ven iz vseh Izraelovih mest, pojoč in plešoč, da srečajo kralja Savla z bobniči, z radostjo in z glasbenimi instrumenti.',
        7: 'Ženske so odgovarjale druga drugi, medtem ko so igrale in govorile: »Savel je umoril svoje tisoče, David pa svoje deset tisoče.«',
        8: 'Savel je bil zelo ogorčen in [to] govorjenje mu ni ugajalo in je rekel: »Davidu so pripisale deset tisoče, meni pa so pripisale samo tisoče. Kaj ima lahko več kakor kraljestvo?«',
        9: 'Savel je od tistega dne dalje Davida opazoval.',
        10: '§ Pripetilo se je naslednji dan, da je nad Savla prišel zli duh od Boga in je prerokoval v sredi hiše. David pa je igral s svojo roko kakor ob drugih časih. V Savlovi roki pa je bilo kopje.',
        11: 'Savel je zalučal kopje, kajti rekel je: » S tem bom Davida udaril celo k zidu.« David pa se je dvakrat izognil njegovi prisotnosti.',
        12: 'Savel se je bal Davida, ker je bil Gospod z njim, od Savla pa je odšel.',
        13: 'Zato ga je Savel odstranil od sebe in ga postavil za poveljnika nad tisočimi in odhajal in prihajal je pred ljudstvom.',
        14: 'David se je na vseh svojih poteh obnašal modro in Gospod je bil z njim.',
        15: 'Zato se ga je Savel, ko je videl, da se je obnašal zelo modro, bal.',
        16: 'Toda ves Izrael in Juda je ljubil Davida, zato ker je odhajal in prihajal pred njimi.',
        17: 'Savel je rekel Davidu: »Glej mojo starejšo hči Merábo, njo ti bom dal za ženo, samo hraber bodi zame in bojuj Gospodove boje.« Kajti Savel je rekel: »Naj moja roka ne bo nad njim, temveč naj bo nad njim roka Filistejcev.«',
        18: 'David je rekel Savlu: »Kdo sem jaz? In kaj je moje življenje ali družina mojega očeta v Izraelu, da bi bil kraljev zet?«',
        19: 'Toda pripetilo se je ob času, ko naj bi bila Savlova hči Merába dana Davidu, da je bila dana za ženo Mehólčanu Adriélu.',
        20: 'Savlova hči Mihála je ljubila Davida in povedali so Savlu in stvar mu je ugajala.',
        21: 'Savel je rekel: »Dal mu jo bom, da mu bo lahko za zanko in da bo roka Filistejcev lahko zoper njega.« Zato je Savel rekel Davidu: »Danes boš moj zet z eno od dveh.«',
        22: 'Savel je zapovedal svojim služabnikom, rekoč: »Na skrivaj se pogovarjajte z Davidom in recite: ›Glej, kralj se razveseljuje v tebi in vsi njegovi služabniki te ljubijo. Sedaj torej postani kraljev zet.‹«',
        23: 'Savlovi služabniki so te besede govorili na Davidova ušesa. David je rekel: »Ali se vam zdi to lahka stvar postati kraljev zet, glede na to, da sem revež in preziran?«',
        24: 'Savlovi služabniki so mu povedali, rekoč: »David je govoril na ta način.«',
        25: 'Savel je rekel: »Tako boste rekli Davidu: ›Kralj ne želi nobene dote, temveč sto prednjih kožic Filistejcev, da bi bil maščevan nad kraljevimi sovražniki.‹« Toda Savel je mislil, da bi Davidu povzročil pasti po roki Filistejcev.',
        26: 'Ko so njegovi služabniki te besede povedali Davidu, je Davidu ugajalo, da bi bil kraljev zet in dnevi še niso pretekli.',
        27: 'Zato je David vstal in odšel, on in njegovi možje in izmed Filistejcev so usmrtili dvesto mož. David je prinesel njihove prednje kožice in v polnem številu so jih izročili kralju, da bi postal kraljev zet. In Savel mu je dal svojo hčer Mihálo za ženo.',
        28: 'Savel je videl in spoznal, da je bil Gospod z Davidom in da ga je Savlova hči Mihála ljubila.',
        29: 'Savel pa se je še bolj bal Davida in Savel je dnevno postajal Davidov sovražnik.',
        30: '§ Potem so princi Filistejcev odšli naprej in pripetilo se je, potem ko so šli naprej, da se je David obnašal bolj modro kakor vsi Savlovi služabniki, tako da je bilo njegovo ime zelo cenjeno.',
    },
    19: {
        1: 'Savel je spregovoril svojemu sinu Jonatanu in vsem svojim služabnikom, da naj ubijejo Davida.',
        2: 'Toda Savlov sin Jonatan se je zelo veselil v Davidu, in Jonatan je povedal Davidu, rekoč: »Moj oče Savel si prizadeva, da te ubije. Sedaj torej, prosim te, pazi nase do jutra in ostani na skritem mestu in se skrij,',
        3: 'jaz pa bom šel ven in stal poleg svojega očeta na polju, kjer si ti in se bom s svojim očetom posvetoval o tebi in kar vidim, to ti bom povedal.«',
        4: 'Jonatan je svojemu očetu Savlu govoril dobro o Davidu in mu rekel: »Naj kralj ne greši zoper svojega služabnika, zoper Davida, ker on ni grešil zoper tebe in ker so bila njegova dela do tebe zelo dobra,',
        5: 'kajti ali ni svojega življenja položil v svojo roko in usmrtil Filistejca in je Gospod izvršil veliko rešitev duš za ves Izrael. Ti si to videl in si se veselil. Zakaj potem hočeš grešiti zoper nedolžno kri, da bi Davida ubil brez razloga?«',
        6: 'Savel je prisluhnil Jonatanovemu glasu in Savel je prisegel: » Kakor živi Gospod, on ne bo umorjen.«',
        7: 'Jonatan je poklical Davida in Jonatan mu je pokazal vse te stvari. Jonatan je Davida privedel k Savlu in bil je v njegovi prisotnosti, kakor v preteklih časih.',
        8: 'Tam je bila ponovno vojna in David je odšel ven in se boril s Filistejci in jih usmrtil z velikim pokolom in oni so zbežali od njega.',
        9: 'Zli duh od Gospoda je bil nad Savlom, ko je sedel v svoji hiši, s svojim kopjem v svoji roki in David je igral s svojo roko.',
        10: 'Savel si je prizadeval, da s kopjem udari Davida, celo k zidu, toda ta se je izmuznil iz Savlove prisotnosti in kopje je zapičil v zid, David pa je zbežal in tisto noč pobegnil.',
        11: 'Savel je tudi k Davidovi hiši poslal poslance, da ga stražijo in da ga zjutraj ubijejo. In Davidova žena Mihála mu je povedala, rekoč: »Če nocoj ne rešiš svojega življenja, boš jutri umorjen.«',
        12: 'Tako je Mihála Davida spustila navzdol skozi okno in odšel je, bežal ter pobegnil.',
        13: 'Mihála pa je vzela kip in ga položila na posteljo in za njegov vzglavnik položila blazino iz kozje dlake in to pokrila z obleko.',
        14: 'Ko je Savel poslal poslance, da primejo Davida, je rekla: »Bolan je.«',
        15: 'Savel je ponovno poslal poslance, da vidijo Davida, rekoč: »Privedite ga gor k meni v postelji, da ga bom lahko ubil.«',
        16: 'Ko so poslanci vstopili, glej, je bil v postelji kip, z blazino iz kozje dlake za njegov vzglavnik.',
        17: 'Savel je rekel Miháli: »Zakaj si me tako zavedla in mojega sovražnika poslala proč, da je pobegnil?« Mihála je Savlu odgovorila: »Rekel mi je: ›Pusti me oditi; čemu bi te ubil?‹«',
        18: 'Tako je David bežal, pobegnil in prišel k Samuelu v Ramo ter mu povedal vse, kar mu je Savel storil. In on in Samuel sta odšla ter prebivala v Najótu.',
        19: 'To je bilo povedano Savlu, rekoč, poglej: »David je pri Najótu v Rami.«',
        20: 'Savel je poslal poslance, da primejo Davida. Ko pa so ti zagledali skupino prerokov, ki je prerokovala in Samuela stati kot določenega nad njimi, je bil Božji Duh nad Savlovimi poslanci in tudi oni so prerokovali.',
        21: 'Ko je bilo to povedano Savlu, je poslal druge poslance in tudi ti so prerokovali. In Savel je ponovno, tretjič, poslal poslance in tudi ti so prerokovali.',
        22: 'Potem je tudi sam odšel v Ramo in prišel k velikemu vodnjaku, ki je v Sehuju. Vprašal je in rekel: »Kje sta Samuel in David?« Nekdo je rekel: »Glej, onadva sta pri Najótu v Rami.«',
        23: 'In odšel je tja k Najótu v Ramo in Božji Duh je bil tudi nad njim in šel je naprej in prerokoval, dokler ni prišel k Najótu v Ramo.',
        24: 'Tudi on je slekel svoja oblačila in na podoben način prerokoval pred Samuelom in ves ta dan in vso noč ležal gol. Zato pravijo: » Ali je tudi Savel med preroki?«',
    },
    20: {
        1: 'David je pobegnil iz Najóta v Rami in prišel ter pred Jonatanom rekel: »Kaj sem storil? Kaj je moja krivda? Kakšen je moj greh pred tvojim očetom, da mi streže po življenju?«',
        2: 'Rekel mu je: »Bog ne daj. Ne boš umrl. Glej, moj oče ne bo storil ničesar, ali velikega ali malega, razen, da mi bo to pokazal. Zakaj bi moj oče to stvar skril pred menoj? To ni tako.«',
        3: 'David je poleg tega prisegel in rekel: »Tvoj oče zagotovo ve, da sem našel milost v tvojih očeh.« Rekel je: »Naj Jonatan tega ne izve, da ne bi bil užaloščen, toda resnično, kakor živi Gospod in kakor živi tvoja duša, je samo korak med menoj in smrtjo.«',
        4: 'Potem je Jonatan rekel Davidu: »Karkoli želi tvoja duša, celo to bom storil zate.«',
        5: 'David je Jonatanu rekel: »Glej, jutri je mlaj in jaz naj ne bi manjkal sedeti s kraljem pri mizi. Toda pusti mi oditi, da se lahko skrijem na polju do tretjega dne zvečer.',
        6: 'Če me tvoj oče sploh pogreši, potem reci: ›David je iskreno prosil oditi od mene, da lahko teče v svoje mesto Betlehem, kajti tam je letna klavna daritev za vso družino.‹',
        7: 'Če reče tako: › To je dobro,‹ bo tvoj služabnik imel mir. Toda če bo zelo ogorčen, potem bodi prepričan, da je po njem določeno zlo.',
        8: 'Zato boš prijazno postopal s svojim služabnikom, kajti svojega služabnika si privedel v Gospodovo zavezo s seboj. Vendar če bo v meni krivičnost, me sam ubij, kajti zakaj bi me privedel k svojemu očetu?«',
        9: 'Jonatan je rekel: »To bodi daleč od tebe, kajti če zagotovo izvem, da je bilo po mojem očetu določeno zlo, da pride nadte, mar ti ne bi potem tega povedal?«',
        10: 'Potem je David rekel Jonatanu: »Kdo mi bo povedal? Ali kaj če ti tvoj oče odgovori surovo?«',
        11: 'Jonatan je rekel Davidu: »Pridi in pojdiva ven na polje.« In oba izmed njiju sta odšla na polje.',
        12: 'Jonatan je rekel Davidu: »Oh Gospod, Izraelov Bog, ko bom kadarkoli slišal svojega očeta, jutri ali tretji dan in glej, če bo dobro do Davida in potem ne pošljem k tebi in ti tega ne pokažem;',
        13: 'Gospod stori tako in mnogo več Jonatanu. Toda če to ugaja mojemu očetu, da ti stori zlo, potem ti bom to pokazal in te poslal proč, da boš lahko šel v miru, in Gospod bodi s teboj, kakor je bil z mojim očetom.',
        14: 'Dokler še živim ne boš samo meni izkazoval Gospodove prijaznosti, da ne umrem,',
        15: 'temveč tudi svoje prijaznosti ne boš odsekal od moje hiše na veke. Ne, niti ko je Gospod odsekal Davidove sovražnike, vsakega iz obličja zemlje.«',
        16: 'Tako je Jonatan sklenil zavezo z Davidovo hišo, rekoč: »Naj Gospod to celo zahteva pri roki Davidovih sovražnikov.«',
        17: 'Jonatan je Davidu dal, da je ponovno prisegel, ker ga je ljubil, kajti ljubil ga je, kakor je ljubil svojo lastno dušo.',
        18: 'Potem je Jonatan rekel Davidu: »Jutri je mlaj in ti boš pogrešan, ker bo tvoj sedež prazen.',
        19: 'Ko boš tri dni ostal, potem boš hitro šel dol in prišel h kraju, kjer si se skril, ko je bilo opravilo v roki in ostal boš pri kamnu Ezelu.',
        20: 'Jaz pa bom izstrelil tri puščice na tej strani, kakor če streljam v tarčo.',
        21: 'Glej, poslal bom dečka, rekoč: ›Pojdi, najdi puščice.‹ Če bom dečku izrecno rekel: ›Glej, puščice so na tej tvoji strani, vzemi jih,‹ potem pridi, kajti tam je zate mir in nobene škode, kakor Gospod živi.',
        22: 'Toda če mladeniču rečem tako: ›Glej, puščice so onstran tebe,‹ pojdi svojo pot, kajti Gospod te pošilja proč.',
        23: 'Glede zadeve, o kateri sva govorila, glej, Gospod bodi med menoj in teboj na veke.«',
        24: 'Tako se je David skril na polju. Ko je prišel mlaj, se je kralj usedel, da jé hrano.',
        25: 'Kralj je sedel na svojem sedežu, kakor ob drugih časih, torej sedežu pri zidu in Jonatan je vstal in Abnêr je sedel pri Savlovi strani, Davidovo mesto pa je bilo prazno.',
        26: 'Kljub temu Savel ta dan ni spregovoril nobene stvari, kajti mislil je: »Nekaj se mu je pripetilo, ni čist. Zagotovo ni čist.«',
        27: 'Pripetilo se je naslednji dan, ki je bil drugi dan meseca, da je bil Davidov prostor prazen. Savel je rekel svojemu sinu Jonatanu: »Zakaj ne prihaja Jesejev sin k jedi niti včeraj niti danes.«',
        28: 'Jonatan je odgovoril Savlu: »David me je iskreno prosil za dovoljenje, da gre v Betlehem.',
        29: 'Rekel je: ›Pusti me oditi, prosim te, kajti naša družina ima klavno daritev v mestu in moj brat mi je zapovedal, naj bom tam in sedaj, če sem našel naklonjenost v tvojih očeh, mi pusti oditi, prosim te in videti svoje brate.‹ Zato ne prihaja h kraljevi mizi.«',
        30: 'Potem je bila Savlova jeza vžgana zoper Jonatana in mu je rekel: »Ti, sin sprevržene uporne ženske, mar ne vem, da si si izbral Jesejevega sina v svojo lastno zmedo in k zmedi nagote svoje matere?',
        31: 'Kajti dokler Jesejev sin živi na zemlji, ne boš utrjen niti tvoje kraljestvo. Zato sedaj pošlji in mi ga pripelji, kajti zagotovo bo umrl.«',
        32: 'Jonatan je svojemu očetu Savlu odgovoril in mu rekel: »Zakaj naj bi bil umorjen? Kaj je storil?«',
        33: 'Savel je vanj vrgel kopje, da ga pobije, po čemer je Jonatan vedel, da je bilo od njegovega očeta odločeno, da Davida usmrti.',
        34: 'Tako je Jonatan v siloviti jezi vstal od mize in drugi dan meseca ni jedel nobene hrane, kajti užaloščen je bil zaradi Davida, ker mu je oče storil sramoto.',
        35: 'Pripetilo se je zjutraj, da je Jonatan odšel na polje ob času, dogovorjenem z Davidom in majhen deček z njim.',
        36: 'Svojemu dečku je rekel: »Steci, poišči sedaj puščice, ki jih izstrelim.« In medtem ko je deček stekel, je izstrelil puščico preko njega.',
        37: 'Ko je deček prišel na mesto puščice, ki jo je Jonatan izstrelil, je Jonatan zaklical za dečkom in rekel: » Ali ni puščica onstran tebe?«',
        38: 'Jonatan je zaklical za dečkom: »Podvizaj se, pohiti, ne stoj.« Jonatanov deček je zbral puščice in prišel k svojemu gospodarju.',
        39: 'Toda deček ni vedel nobene stvari. Samo Jonatan in David sta poznala zadevo.',
        40: 'Jonatan je izročil svoje strelno orožje svojemu dečku in mu rekel: »Pojdi, odnesi jih v mesto.«',
        41: 'In brž ko je deček odšel, se je David dvignil iz kraja proti jugu in padel na svoj obraz na tla in se trikrat priklonil. Drug drugega sta poljubila in jokala drug z drugim, dokler David ni prevladal [v joku].',
        42: 'Jonatan je rekel Davidu: »Pojdi v miru, kakor sva oba izmed naju prisegla v Gospodovem imenu, rekoč: ›GOSPOD bodi med menoj in teboj in med mojim semenom in tvojim semenom na veke.‹« In vstal je ter odpotoval, Jonatan pa je odšel v mesto.',
    },
    21: {
        1: 'Potem je David prišel v Nob, k duhovniku Ahimélehu in Ahiméleh se je bal ob srečanju z Davidom in mu je rekel: »Zakaj si sam in ni nikogar s teboj?«',
        2: 'David je rekel duhovniku Ahimélehu: »Kralj mi je zapovedal opravilo in mi rekel: ›Naj noben človek ne izve karkoli o opravilu, s katerim te pošiljam in kaj sem ti zapovedal in svoje služabnike sem določil na takšen in takšen kraj.‹',
        3: 'Zdaj torej kaj je pod tvojo roko? Daj mi pet hlebov kruha v roko ali kar je prisotnega.«',
        4: 'Duhovnik je Davidu odgovoril in rekel: » Tam ni običajnega kruha pod mojo roko, temveč je posvečen kruh, če so se vsaj mladeniči zadržali pred ženskami.«',
        5: '§ David je odgovoril duhovniku in mu rekel: »Resnično so bile ženske zadržane pred nami te tri dni, odkar sem prišel ven in posode mladeničev so svete in kruh je nekako običajen, da, kot bi bil ta dan posvečen v posodi.«',
        6: 'Tako mu je duhovnik dal posvečenega kruha, kajti tam ni bilo kruha, razen hleba navzočnosti, kar je bilo vzeto izpred Gospoda, da se položi vroč kruh na dan, ko je bil ta vzet.',
        7: 'Torej nek mož izmed Savlovih služabnikov se je ta dan zadrževal tam pred Gospodom in njegovo ime je bilo Doég, Edómec, glavni izmed črednikov, ki so pripadali Savlu.',
        8: 'David je rekel Ahimélehu: »In ali ni tukaj pod tvojo roko sulica ali meč? Kajti s seboj nisem prinesel niti svojega meča niti svojih orožij, ker je kraljev posel zahteval naglico.«',
        9: 'Duhovnik je rekel: »Meč Filistejca Goljata, ki si ga umoril v dolini Elá, glej, ta je tukaj, za efódom zavit v oblačilo. Če hočeš vzeti tega, ga vzemi, kajti nobenega drugega ni, razen tega tukaj.« David je rekel: »Nobenega ni podobnega temu; daj mi ga.«',
        10: 'David se je vzdignil in tisti dan iz strahu pred Savlom pobegnil in šel k Ahíšu, kralju v Gatu.',
        11: 'Ahíševi služabniki so mu rekli: » Ali ni to David, kralj dežele? Ali niso prepevale druga drugi o njem v plesih, rekoč: ›Savel je umoril svoje tisoče, David pa svoje deset tisoče?‹«',
        12: 'David si je te besede položil v svoje srce in se boleče bal Ahíša, kralja iz Gata.',
        13: 'Pred njimi je spremenil svoje obnašanje in v njihovih rokah se je hlinil zmešanega in praskal po vhodih velikih vrat in si svojo slino pustil izlivati na svojo brado.',
        14: 'Potem je Ahíš rekel svojim služabnikom: »Glejte no! Vidite, človek je zmešan. Zakaj ste ga torej privedli k meni?',
        15: 'Mar potrebujem zmešanih ljudi, da ste pripeljali tega pajdaša, da igra norca v moji prisotnosti? Ali naj ta pajdaš pride v mojo hišo?«',
    },
    22: {
        1: 'David je torej odpotoval od tam in pobegnil v votlino Adulám. Ko so njegovi bratje in vsa hiša njegovega očeta to slišali, so odšli dol, tja k njemu.',
        2: 'K njemu so se zbrali skupaj vsak, kdor je bil v stiski in vsak, kdor je bil v dolgu in vsak, kdor je bil nezadovoljen; in postal je poveljnik nad njimi in tam je bilo z njim okoli štiristo mož.',
        3: 'David je od tam odšel v moábsko Micpo in moabskemu kralju rekel: »Naj moj oče in moja mati, prosim te, prideta naprej in bosta s teboj, dokler ne izvem kaj bo Bog storil zame.«',
        4: 'In privedel ju je pred moábskega kralja in prebivala sta z njim ves čas, ko je bil David v utrjenem kraju.',
        5: 'Prerok Gad je rekel Davidu: »Ne prebivaj v utrjenem kraju. Odidi in pojdi v Judovo deželo.« Potem je David odrinil in prišel v gozd Heret.',
        6: 'Ko je Savel slišal, da so odkrili Davida in može, ki so bili z njim (torej Savel je prebival v Gíbei, pod drevesom v Rami, s svojo sulico v svoji roki in vsi njegovi služabniki so stali okoli njega),',
        7: 'je potem Savel rekel svojim služabnikom, ki so stali okoli njega: »Poslušajte torej, vi Benjaminovci, ali bo Jesejev sin vsakemu izmed vas dal polja in vinograde in vas vse postavil za poveljnike nad tisočimi in poveljnike nad stotimi,',
        8: 'da ste se vsi izmed vas zarotili zoper mene in tam ni nikogar, ki mi kaže, da je moj sin sklenil dogovor z Jesejevim sinom in tam ni nikogar izmed vas, ki mu je žal zame ali mi kaže, da je moj sin zoper mene razvnel mojega služabnika, da preži v zasedi, kakor ta dan?«',
        9: 'Potem je odgovoril Edómec Doég, ki je bil postavljen nad Savlove služabnike in rekel: »Videl sem Jesejevega sina prihajati v Nob, k Ahitúbovemu sinu Ahimélehu.',
        10: 'Ta je od Gospoda povprašal zanj in dal mu je živež in dal mu je meč Filistejca Goljata.«',
        11: 'Potem je kralj poslal, da pokliče duhovnika Ahiméleha, Ahitúbovega sina in vso hišo njegovega očeta, duhovnike, ki so bili v Nobu in vsi izmed njih so prišli h kralju.',
        12: 'Savel je rekel: »Poslušaj sedaj ti, Ahitúbov sin.« Ta je odgovoril: »Tukaj sem, moj gospod.«',
        13: 'Savel mu je rekel: »Zakaj sta se zarotila zoper mene, ti in Jesejev sin, v tem, da si mu dal kruha in meč in si od Boga poizvedel zanj, da bi on vstal zoper mene, da preži v zasedi kakor na ta dan?«',
        14: 'Potem je Ahiméleh odgovoril kralju in rekel: »Kdo je tako zvest med vsemi tvojimi služabniki kakor David, ki je kraljev zet in gre ob tvojem ukazu in je častitljiv v tvoji hiši?',
        15: 'Ali sem takrat začel poizvedovati od Boga zanj? To bodi daleč od mene. Naj kralj ne pripiše kakršnekoli stvari svojemu služabniku niti vsej hiši mojega očeta, kajti tvoj služabnik ni vedel nič od vsega tega, manj ali več.«',
        16: 'Kralj je rekel: »Zagotovo boš umrl, Ahiméleh, ti in vsa hiša tvojega očeta.«',
        17: 'Kralj je rekel pešcem, ki so stali okoli njega: »Obrnite se in ubijte Gospodove duhovnike, ker je tudi njihova roka z Davidom in ker so vedeli, ko je on pobegnil, pa mi tega niso pokazali.« Toda kraljevi služabniki niso hoteli iztegniti svoje roke, da pade na Gospodove duhovnike.',
        18: 'Kralj je rekel Doégu: »Ti se obrni in padi nad duhovnike.« In Edómec Doég se je obrnil in padel nad duhovnike in jih na ta dan usmrtil petinosemdeset oseb, ki so nosili lanen efód.',
        19: 'Nob, mesto duhovnikov, je udaril z ostrino meča, tako moške kakor ženske, otroke in dojenčke, vole, osle in ovce, z ostrino meča.',
        20: 'Eden izmed Ahimélehovih sinov, Ahitúbov sin, imenovan Abjatár, pa je ušel in pobegnil za Davidom.',
        21: 'Abjatár je pokazal Davidu, da je Savel umoril Gospodove duhovnike.',
        22: 'David je rekel Abjatárju: »Vedel sem to ta dan, ko je bil tam Edómec Doég, da bo zagotovo povedal Savlu. Povzročil sem smrt vseh oseb hiše tvojega očeta.',
        23: 'Ostani z menoj, ne boj se, kajti kdor streže po mojem življenju, streže po tvojem življenju. Toda z menoj boš na varnem.«',
    },
    23: {
        1: 'Potem so povedali Davidu, rekoč: »Glej, Filistejci se bojujejo zoper Keílo in ropajo mlatišča.«',
        2: 'Zato je David poizvedel od Gospoda, rekoč: »Ali naj grem in udarim te Filistejce?« Gospod je rekel Davidu: »Pojdi in udari Filistejce in reši Keílo.«',
        3: 'Davidovi ljudje so mu rekli: »Glej, bojimo se tukaj v Judu. Koliko bolj potem, če pridemo v Keílo zoper vojske Filistejcev?«',
        4: 'Potem je David ponovno poizvedel od Gospoda. In Gospod mu je odgovoril ter rekel: »Vstani, pojdi dol v Keílo, kajti jaz bom Filistejce izročil v tvojo roko.«',
        5: 'Tako so David in njegovi ljudje odšli v Keílo in se borili s Filistejci in odvedli njihovo živino in jih udarili z velikim pokolom. Tako je David rešil prebivalce Keíle.',
        6: 'Pripetilo se je, ko je Ahimélehov sin Abjatár pobegnil k Davidu v Keílo, da je ta prišel dol z efódom v svoji roki.',
        7: 'Savlu je bilo povedano to, da je David prišel v Keílo. Savel je rekel: »Bog ga je izročil v mojo roko, kajti z vstopom v mesto, ki ima velika vrata in zapahe, je zaprt noter.«',
        8: 'Savel je vse ljudstvo sklical skupaj k vojni, da gredo dol v Keílo, da oblegajo Davida in njegove može.',
        9: 'David pa je vedel, da je Savel zoper njega skrivno izvajal vragolijo in duhovniku Abjatárju je rekel: »Prinesi sèm efód.«',
        10: 'Potem je David rekel: »Oh Gospod, Izraelov Bog, tvoj služabnik je zagotovo slišal, da Savel išče, da bi prišel v Keílo, da zaradi mene uniči mesto.',
        11: 'Ali me bodo možje iz Keíle izročili v njegovo roko? Ali bo Savel prišel dol, kakor je tvoj služabnik slišal? Oh Gospod, Izraelov Bog, rotim te, povej svojemu služabniku.« Gospod je rekel: »Prišel bo dol.«',
        12: 'Potem je David rekel: »Ali bodo možje iz Keíle izročili mene in moje ljudi v Savlovo roko?« Gospod je rekel: »Izročili te bodo.«',
        13: 'Potem so David in njegovi možje, ki jih je bilo okoli šeststo, vstali in odrinili iz Keíle in odšli, kamor so lahko šli. To je bilo povedano Savlu, da je David pobegnil iz Keíle in ta je opustil, da gre naprej.',
        14: 'David je prebival v divjini, v oporiščih in ostal na gori, v divjini Zif. Savel ga je vsak dan iskal, toda Bog ga ni izročil v njegovo roko.',
        15: 'David je videl, da je Savel prišel ven, da bi stregel po njegovem življenju in David je bil v Zifski divjini, v gozdu.',
        16: 'Savlov sin Jonatan je vstal in odšel k Davidu v gozd in okrepil njegovo roko v Bogu.',
        17: 'Rekel mu je: »Ne boj se, kajti roka mojega očeta Savla te ne bo našla. Ti boš kralj nad Izraelom in jaz bom poleg tebe in to tudi moj oče Savel ve.«',
        18: 'Onadva sta sklenila zavezo pred Gospodom in David je ostal v gozdu, Jonatan pa je odšel k svoji hiši.',
        19: '§ Potem so prišli gor Zífovci k Savlu v Gíbeo, rekoč: »Ali se ne skriva David z nami v oporiščih v gozdu, na hribu Hahíla, ki je na jugu Ješimona?',
        20: 'Zdaj torej, oh kralj, pridi dol glede na vso željo svoje duše, da prideš dol in naš del bo, da ga izročimo v kraljevo roko.«',
        21: 'Savel je rekel: »Blagoslovljeni bodite od Gospoda, kajti do mene imate sočutje.',
        22: 'Pojdite, prosim vas, še pripravite in spoznajte in poglejte na njegov kraj, kjer je njegovo shajališče in kdo ga je videl tam, kajti povedano mi je, da postopa zelo premeteno.',
        23: 'Glejte torej in vzemite spoznanje o vseh skrivnih krajih, kjer se sam skriva in ponovno pridite k meni z gotovostjo in jaz bom šel z vami in zgodilo se bo, če bo v deželi, da ga bom poiskal med vsemi Judovimi tisočimi.«',
        24: '§ Vstali so in pred Savlom odšli v Zif, toda David in njegovi ljudje so bili v Maónski divjini, na ravnini, južno od Ješimona.',
        25: 'Tudi Savel in njegovi ljudje so odšli, da ga iščejo. Davidu so povedali, zato je prišel dol v skalo in ostal v Maónski divjini. Ko je Savel to slišal, je zasledoval Davida v Maónski divjini.',
        26: 'Savel je šel po tej strani gore, David in njegovi ljudje pa po oni strani gore. David se je podvizal, da odide zaradi strahu pred Savlom, kajti Savel in njegovi ljudje so obkolili Davida in njegove može okrog in okrog, da jih zgrabijo.',
        27: 'Toda k Savlu je prišel poslanec, rekoč: »Pohiti in pridi, kajti Filistejci so vdrli v deželo.«',
        28: 'Zato se je Savel vrnil od zasledovanja za Davidom in odšel zoper Filistejce. Zato so ta kraj imenovali Sela-hamah-lekot.',
        29: 'David se je dvignil od tam in prebival v oporiščih pri En Gediju.',
    },
    24: {
        1: 'Pripetilo se je, ko se je Savel vrnil iz zasledovanja Filistejcev, da mu je bilo povedano, rekoč: »Glej, David je v divjini En Gedi.«',
        2: 'Potem je Savel vzel tri tisoč izbranih mož iz vsega Izraela in odšel, da poišče Davida in njegove ljudi na skalah divjih koz.',
        3: 'Ob poti je prišel k stajam za ovce, kjer je bila votlina in Savel je šel noter, da pokrije svoja stopala. David in njegovi možje pa so ostajali ob straneh votline.',
        4: 'Davidovi možje so mu rekli: »Glej, dan, o katerem ti je rekel Gospod: ›Glej, tvojega sovražnika bom izročil v tvojo roko, da mu boš lahko storil, kakor se ti zdi dobro.‹« Potem je David vstal in na skrivnem odsekal krajec Savlovega svečanega oblačila.',
        5: 'Pripetilo se je potem, da ga je Davidovo srce udarilo, ker je odsekal krajec Savlovega oblačila.',
        6: 'Svojim možem je rekel: » Gospod ne daj, da bi storil tako stvar svojemu gospodarju, Gospodovemu maziljencu, da iztegnem svojo roko zoper njega, ker je maziljen od Gospoda.«',
        7: 'Tako je David s temi besedami zadržal svoje služabnike in jim ni pustil, da vstanejo zoper Savla. Toda Savel je vstal iz votline in odšel na svojo pot.',
        8: 'Potem je tudi David vstal in šel ven iz votline in zaklical za Savlom, rekoč: »Moj gospod kralj.« Ko je Savel pogledal za seboj, se je David sklonil s svojim obrazom k zemlji in se priklonil.',
        9: 'David je rekel Savlu: »Zakaj poslušaš besede ljudi, govoreč: ›Glej, David išče tvoje zlo?‹',
        10: 'Glej, ta dan so tvoje oči videle, kako te je Gospod v votlini izročil v mojo roko. Nekateri so mi zaukazali, naj te usmrtim, toda moje oko ti je prizaneslo. Rekel sem: ›Ne bom iztegnil svoje roke zoper svojega gospoda, kajti on je Gospodov maziljenec.‹',
        11: 'Poleg tega, moj oče, glej, da, poglej krajec svojega svečanega oblačila v moji roki, kajti v tem, da sem odsekal krajec tvojega svečanega oblačila in te nisem usmrtil, vedi in vidi, da v moji roki ni niti zla niti prestopka in nisem grešil zoper tebe, vendar ti loviš mojo dušo, da jo vzameš.',
        12: 'Gospod sodi med menoj in teboj in Gospod naj me maščuje nad teboj, toda moja roka ne bo nad teboj.',
        13: 'Kakor pravi pregovor starcev: ›Zlobnost izvira od zlobnih,‹ toda moja roka ne bo nad teboj.',
        14: 'Za kom je Izraelov kralj prišel ven? Za kom tečeš? Za mrtvim psom, za bolho.',
        15: 'Gospod naj bo torej sodnik in sodi med menoj in teboj in gleda in zagovarja mojo pravdo in me osvobodi iz tvoje roke.«',
        16: 'Pripetilo se je, ko je David Savlu prenehal govoriti te besede, da je Savel rekel: » Ali je to tvoj glas, moj sin David?« Savel je povzdignil svoj glas in zajokal.',
        17: 'Davidu je rekel: »Pravičnejši si kakor jaz, kajti nagradil si mi dobro, medtem ko sem ti jaz nagradil zlo.',
        18: 'Danes si pokazal, kako dobro si ravnal z menoj, ker ko me je Gospod izročil v tvojo roko, me nisi ubil.',
        19: 'Kajti če človek najde svojega sovražnika ali ga bo pustil sproščeno oditi? Zato [naj] te Gospod dobro nagradi za to, kar si mi ta dan storil.',
        20: 'Sedaj glej, dobro vem, da boš zagotovo postal kralj in da bo Izraelovo kraljestvo utrjeno v tvoji roki.',
        21: 'Prisezi mi torej sedaj pri Gospodu, da ne boš iztrebil mojega semena za menoj in da ne boš uničil mojega imena iz hiše mojega očeta.«',
        22: 'David je prisegel Savlu. Savel je odšel domov, toda David in njegovi možje so se povzpeli na utrjen kraj.',
    },
    25: {
        1: 'Samuel je umrl in vsi Izraelci so se zbrali skupaj, ga objokovali in ga pokopali v njegovi hiši v Rami. In David je vstal ter odšel dol k Paránski divjini.',
        2: 'Tam je bil mož v Maónu, katerega posesti so bile v Karmelu. Mož je bil zelo velik in imel je tri tisoč ovc in tisoč koz, in svoje ovce je strigel v Karmelu.',
        3: 'Torej moževo ime je bilo Nabál in ime njegove žene Abigájila. Bila je ženska dobrega razumevanja in krasnega obličja, toda mož je bil skopušen in hudoben v svojih dejanjih. Bil je iz Kalébove hiše.',
        4: 'David je v divjini slišal, da je Nabál strigel svoje ovce.',
        5: 'David je poslal ven deset mladeničev in David je mladeničem rekel: »Povzpnite se gor do Karmela in pojdite k Nabálu ter ga pozdravite v mojem imenu.',
        6: 'Tako boste rekli njemu, ki živi v uspevanju: ›Mir bodi tako tebi in mir bodi tvoji hiši in mir bodi vsemu, kar imaš.',
        7: 'Sedaj sem slišal, da si imel strižce. Torej tvoji pastirji, ki so bili z nami, jih nismo poškodovali niti jim ni ničesar zmanjkalo, vse dokler so bili v Karmelu.',
        8: 'Vprašaj svoje mladeniče in ti bodo pokazali. Zato naj tvoji mladeniči najdejo naklonjenost v tvojih očeh, kajti prišli smo na dober dan. Daj, prosim te, karkoli pride k tvoji roki, svojim služabnikom in svojemu sinu Davidu.‹«',
        9: 'Ko so Davidovi mladeniči prišli, so v Davidovem imenu govorili Nabálu glede na vse te besede in prenehali.',
        10: 'Nabál je odgovoril Davidovim služabnikom in rekel: »Kdo je David? Kdo je Jesejev sin? Današnje dni je mnogo služabnikov, ki se odtrgajo, vsak mož od svojega gospodarja.',
        11: 'Mar naj torej vzamem svoj kruh, svojo vodo in svoje meso, ki sem ga zaklal za svoje strižce in ga dam možem, za katere ne vem, od kod so?«',
        12: 'Tako so Davidovi mladeniči obrnili svojo pot in ponovno odšli in prišli ter mu povedali vse te besede.',
        13: 'David je svojim možem rekel: »Opašite vsak mož svoj meč.« Opasali so vsak mož svoj meč in tudi David je opasal svoj meč in tam se je dvignilo za Davidom okoli štiristo mož. Dvesto pa jih je ostalo pri stvareh.',
        14: 'Toda eden izmed mladeničev je povedal Nabálovi ženi Abigájili, rekoč: »Glej, David je iz divjine poslal poslance, da pozdravijo našega gospodarja, on pa se jim je posmehoval.',
        15: 'Toda možje so bili zelo dobri do nas in nismo bili poškodovani niti nismo pogrešali nobene stvari, dokler smo bili seznanjeni z njimi, ko smo bili na poljih.',
        16: 'Bili so nam zid, tako podnevi kakor ponoči, ves čas smo bili z njimi, čuvajoč ovce.',
        17: 'Zdaj torej vedi in preudari, kaj boš storila, kajti zlo je določeno zoper našega gospodarja in zoper vso njegovo družino, kajti on je tak Beliálov sin, da človek ne more govoriti z njim.«',
        18: 'Potem se je Abigájila podvizala in vzela dvesto hlebov, dva vinska meha, pet pripravljenih ovc, pet mer opraženega žita, sto grozdov rozin in dvesto figovih kolačev in jih položila na osle.',
        19: 'Svojim služabnikom je rekla: »Pojdite naprej pred menoj. Glejte, jaz pridem za vami.« Toda svojemu soprogu Nabálu ni povedala.',
        20: 'To je bilo tako, medtem ko je jahala na oslu, da je prišla dol ob zavetju hriba in glej, David in njegovi možje so prihajali dol, nasproti njej in jih je srečala.',
        21: 'Torej David je rekel: »Zagotovo sem v divjini zaman varoval vse, kar je imel ta pajdaš, tako da ni zmanjkalo ničesar od vsega, kar je pripadalo njemu, on pa mi je povrnil zlo za dobro.',
        22: '§ Tako in še več naj tudi Bog stori Davidovim sovražnikom, če do jutranje svetlobe pustim od vsega, kar pripada njemu, karkoli, kar lula proti zidu.«',
        23: 'Ko je Abigájila zagledala Davida, je pohitela in razbremenila osla in pred Davidom padla na svoj obraz in se priklonila do tal',
        24: 'in padla ob njegovih stopalih ter rekla: »Nad menoj, moj gospod, nad menoj naj bo ta krivičnost. Naj tvoja pomočnica, prosim te, govori v tvoji pozornosti in poslušaj besede svoje pomočnice.',
        25: 'Naj se moj gospod, prosim te, ne ozira na tega Beliálovega moža, celó Nabála, kajti kakor je njegovo ime, takšen je on; Nabál je njegovo ime in bedaštvo je z njim, toda jaz, tvoja pomočnica, nisem videla mladeničev svojega gospoda, ki si jih poslal.',
        26: 'Zdaj torej, moj gospod, kakor živi Gospod in kakor živi tvoja duša, glede na to, da te je Gospod zadržal pred tem, da bi prihajal prelit kri in pred tem, da bi se maščeval s svojo lastno roko, naj bodo torej tvoji sovražniki in tisti, ki iščejo zlo mojemu gospodu, kakor Nabál.',
        27: 'Naj bo sedaj ta blagoslov, ki ga je tvoja pomočnica prinesla mojemu gospodu, dan mladeničem, ki sledijo mojemu gospodu.',
        28: 'Prosim te, odpusti prekršek svoje pomočnice, kajti Gospod bo zagotovo naredil mojemu gospodu zanesljivo hišo, ker moj gospod bojuje Gospodove bitke in vse tvoje dni zlo ni bilo najdeno v tebi.',
        29: 'Vendar se je vzdignil človek, da te preganja in da išče tvojo dušo, toda duša mojega gospoda bo zvezana v svežnju življenja z Gospodom, tvojim Bogom. Duše tvojih sovražnikov, njih bo zalučal ven kakor iz srede prače.',
        30: 'In zgodilo se bo, ko bo Gospod storil mojemu gospodu glede na vse dobro, kar je govoril glede tebe in te določil vladarja nad Izraelom,',
        31: 'da to ne bo žalost tebi niti prizadeto srce mojemu gospodu ali da si brez vzroka prelil kri ali da se je moj gospod sam maščeval, temveč ko bo Gospod dobro postopal z mojim gospodom, takrat se spomni svoje pomočnice.«',
        32: 'David je rekel Abigájili: »Blagoslovljen bodi Gospod, Izraelov Bog, ki te je ta dan poslal, da me srečaš',
        33: 'in blagoslovljen bodi tvoj nasvet in blagoslovljena bodi ti, ki si me ta dan zadržala pred prihajanjem, da prelijem kri in pred maščevanjem sebe s svojo lastno roko.',
        34: '§ Kajti zagotovo, kakor Gospod, Izraelov Bog, živi, ki me je zadržal pred tem, da ti škodujem, razen če ne bi pohitela in prišla, da me srečaš, zagotovo ne bi do jutranje svetlobe Nabálu ostalo karkoli, kar lula proti zidu.«',
        35: 'Tako je David iz njene roke prejel to, kar mu je prinesla in ji rekel: »Pojdi gor v miru k svoji hiši. Glej, prisluhnil sem tvojemu glasu in sprejel tvojo osebo.«',
        36: 'Abigájila je prišla k Nabálu in glej, v svoji hiši je imel zabavo, kakor kraljevo zabavo. Nabálovo srce je bilo veselo znotraj njega, kajti bil je zelo pijan. Zato mu ni ničesar povedala, manj ali več, do jutranje svetlobe.',
        37: 'Toda zjutraj se je pripetilo, ko je vino odšlo iz Nabála in mu je njegova žena povedala te stvari, da je njegovo srce znotraj njega umrlo in je postal kakor kamen.',
        38: 'Pripetilo se je okoli deset dni kasneje, da je Gospod udaril Nabála, da je umrl.',
        39: 'Ko je David slišal, da je bil Nabál mrtev, je rekel: »Blagoslovljen bodi Gospod, ki je zagovarjal zadevo moje graje pred Nabálovo roko in je svojega služabnika obvaroval pred zlom, kajti Gospod je Nabálovo zlobnost povrnil na njegovo lastno glavo.« In David je poslal in se posvetoval z Abigájilo, da si jo vzame k sebi za ženo.',
        40: 'Ko so Davidovi služabniki prišli k Abigájili v Karmel, so ji spregovorili, rekoč: »David nas je poslal k tebi, da te vzame k sebi za ženo.«',
        41: 'Vzdignila se je, se priklonila na svoj obraz k zemlji in rekla: »Glej, naj bo tvoja pomočnica služabnica, da umiva stopala služabnikov mojega gospoda.«',
        42: 'Abigájila je pohitela, vstala ter jahala na oslu s petimi svojimi gospodičnami, ki so šle za njo in odšla je za Davidovimi poslanci ter postala njegova žena.',
        43: 'David je vzel tudi Ahinóam iz Jezreéla in obe izmed njiju sta bili njegovi ženi.',
        44: 'Toda Savel je dal svojo hčer Mihálo, Davidovo ženo, Paltíju, Lajiševemu sinu, ki je bil iz Galíma.',
    },
    26: {
        1: '§ Zífovci so prišli k Savlu v Gíbeo, rekoč: »Ali se David ne skriva na hribu Hahíla, ki je pred Ješimonom?«',
        2: 'Potem se je Savel dvignil in odšel dol k Zifski divjini in s seboj je imel tri tisoč izbranih mož iz Izraela, da Davida poiščejo v Zifski divjini.',
        3: '§ Savel je taboril na hribu Hahíla, ki je ob poti pred Ješimonom. Toda David je prebival v divjini in videl je, da je Savel prišel za njim v divjino.',
        4: 'David je torej odposlal oglednike in razumel, da je Savel zagotovo prišel.',
        5: 'David je vstal in prišel na kraj, kjer se je Savel utaboril in David je opazoval kraj, kjer sta se ulegla Savel in Abnêr, Nerov sin, poveljnik njegove vojske. Savel pa je ležal v okopu in ljudstvo je taborilo okoli njega.',
        6: 'Potem je David odgovoril in rekel Hetejcu Ahimélehu in Cerújinemu sinu Abišáju, Joábovemu bratu, rekoč: »Kdo bo odšel z menoj dol, k Savlu v tabor?« Abišáj je rekel: »Jaz bom odšel dol s teboj.«',
        7: 'Tako sta David in Abišáj prišla ponoči k ljudstvu in glej, Savel je speč ležal znotraj okopa in njegova sulica zapičena v tla pri njegovem vzglavniku, toda Abnêr in ljudstvo so ležali naokoli njega.',
        8: 'Potem je Abišáj rekel Davidu: »Bog je ta dan izročil tvoje sovražnike v tvojo roko. Zdaj naj ga torej udarim, prosim te, s sulico celo k zemlji in ne bom ga udaril drugič.«',
        9: 'David je rekel Abišáju: »Ne uniči ga, kajti kdo lahko iztegne svojo roko zoper Gospodovega maziljenca in je brez krivde?«',
        10: 'David je nadalje rekel: » Kakor Gospod živi, Gospod ga bo udaril, ali bo prišel njegov dan, da umre, ali [pa] se bo spustil v bitko in umrl.',
        11: 'Gospod me obvaruj, da bi iztegnil svojo roko zoper Gospodovega maziljenca, toda, prosim te, vzemi sedaj sulico, ki je pri njegovem vzglavniku in vrč vode ter odidiva.«',
        12: 'Tako je David vzel sulico in vrč vode izpred Savlovega vzglavnika in spravila sta se proč in noben človek tega ni videl niti ni tega spoznal niti se zbudil, kajti vsi so zaspali, ker je nanje padlo globoko spanje od Gospoda.',
        13: 'Potem je David šel preko, na drugo stran in stal na vrhu oddaljenega hriba. Med njimi je bil velik prostor',
        14: 'in David je zaklical ljudstvu in Nerovemu sinu Abnêrju, rekoč: »Ne odgovarjaš, Abnêr?« Potem je Abnêr odgovoril in rekel: »Kdo si ti, ki kličeš h kralju?«',
        15: 'David je rekel Abnêrju: » Mar nisi ti hraber mož? In kdo je v Izraelu podoben tebi? Zakaj potem nisi varoval svojega gospoda kralja? Kajti tja je prišel nekdo izmed ljudstva, da uniči tvojega gospoda kralja.',
        16: 'Ta stvar, ki si jo storil, ni dobra. Kakor živi Gospod, vredni ste umreti, ker niste varovali svojega gospodarja, Gospodovega maziljenca. In sedaj poglej, kje je kraljeva sulica in vrč vode, ki je bil pri njegovem vzglavniku.«',
        17: 'Savel je prepoznal Davidov glas in rekel: » Ali je to tvoj glas, moj sin David?« David je rekel: » To je moj glas, moj gospod, oh kralj.«',
        18: 'Rekel je: »Zakaj moj gospod tako zasleduje svojega služabnika? Kaj sem storil? Ali kakšno zlo je v moji roki?',
        19: 'Zdaj te torej prosim, naj moj gospod kralj posluša besede svojega služabnika. Če te je Gospod razvnel zoper mene, naj sprejme daritev, toda če so to človeški otroci, naj bodo prekleti pred Gospodom, kajti danes so me pognali ven, pred ostajanjem v Gospodovi dediščini, rekoč: ›Pojdi, služi drugim bogovom.‹',
        20: 'Zdaj naj torej moja kri ne pade na tla pred Gospodovim obrazom, kajti Izraelov kralj je prišel ven, da išče bolho, kakor ko nekdo lovi jerebico v gorah.«',
        21: 'Potem je Savel rekel: »Grešil sem. Vrni se, moj sin David, kajti ne bom ti več škodil, ker je bila ta dan moja duša dragocena v tvojih očeh. Glej igral sem bedaka in se silno motil.«',
        22: 'David je odgovoril in rekel: »Poglej kraljevo sulico! In naj nekdo izmed mladeničev pride čez ter jo vzame.',
        23: 'Gospod [naj] vsakemu možu povrne njegovo pravičnost in njegovo zvestobo, kajti Gospod te je ta dan izročil v mojo roko, toda svoje roke nisem hotel iztegniti zoper Gospodovega maziljenca.',
        24: 'Glej, kakor je bilo tvoje življenje ta dan zelo cenjeno v mojih očeh, tako naj bo moje življenje zelo cenjeno v Gospodovih očeh in naj me osvobodi iz vse stiske.«',
        25: 'Potem je Savel rekel Davidu: »Blagoslovljen bodi ti, moj sin David. Delal boš oboje, velike stvari in vendar boš tudi prevladal.« Tako je David odšel na svojo pot in Savel se je vrnil na svoj kraj.',
    },
    27: {
        1: 'David je v svojem srcu rekel: »Sedaj bom nekega dne umrl po Savlovi roki. Zame ni nič boljšega, kakor da bi hitro pobegnil v deželo Filistejcev in Savel bo obupal nad menoj, da me še išče v kateremkoli območju Izraela. Tako bom pobegnil iz njegove roke.«',
        2: 'David se je dvignil in šel preko s šeststo možmi, ki so bili z njim, k Ahíšu, Maóhovemu sinu, kralju Gata.',
        3: 'David je prebival z Ahíšem v Gatu, on in njegovi možje, vsak mož s svojo družino, David s svojima dvema ženama, Jezreélko Ahinóam in Karmelčanko Abigájilo, Nabálovo ženo.',
        4: 'To je bilo povedano Savlu, da je David pobegnil v Gat in ni ga več ponovno iskal.',
        5: 'David je rekel Ahíšu: »Če sem torej našel milost v tvojih očeh, naj mi dajo prostor v nekem mestu v deželi, da bom tam lahko prebival, kajti zakaj bi tvoj služabnik prebival s teboj v kraljevem mestu?«',
        6: 'Potem mu je Ahíš ta dan izročil Ciklág. Zato Ciklág pripada Judovim kraljem do tega dne.',
        7: 'Časa, ko je David prebival v deželi Filistejcev, je bil polno leto in štiri mesece.',
        8: 'David in njegovi možje so odšli gor in vdrli h Gešuréjcem, Girzéjcem in Amalečanom, kajti ti narodi so bili od davnine prebivalci dežele, kakor greš v Šur, celo v egiptovsko deželo.',
        9: 'David je udaril deželo in ni pustil živega niti moškega niti ženske in odvedel ovce, vole, osle, kamele, obleke in se vrnil in prišel k Ahíšu.',
        10: 'Ahíš je rekel: »Kam ste danes vpadli?« David je rekel: »Zoper južni Juda in zoper jug Jerahmeélovcev in zoper jug Kenéjcev.«',
        11: 'David ni rešil živega niti moškega niti ženske, da prinesejo novice v Gat, rekoč: »Da ne bi povedali o nas, rekoč: ›Tako je storil David in takšen bo njegov način, vse dokler on prebiva v deželi Filistejcev.‹«',
        12: 'Ahíš je verjel Davidu, rekoč: »Svojemu ljudstvu Izraelu je storil, da ga popolnoma prezira, zato bo on moj služabnik na veke.«',
    },
    28: {
        1: 'Pripetilo se je v tistih dneh, da so Filistejci zbrali skupaj svojo vojsko za bojevanje, da se borijo z Izraelom. In Ahíš je rekel Davidu: »Zagotovo vedi, da boš šel z menoj ven v bitko, ti in tvoji možje.«',
        2: 'David je rekel Ahíšu: »Zagotovo boš vedel, kaj lahko tvoj služabnik stori.« Ahíš je rekel Davidu: »Zato te bom na veke naredil za varuha svoje glave.«',
        3: 'Torej Samuel je bil mrtev in ves Izrael ga je objokoval in pokopali so ga v Rami, celo v njegovem lastnem mestu. In Savel je iz dežele odstranil tiste, ki so imeli osebne duhove in čarovnike.',
        4: 'Filistejci so se zbrali skupaj in prišli ter se utaborili v Šunému, in Savel je zbral skupaj ves Izrael in utaborili so se v Gilbói.',
        5: 'Ko je Savel videl vojsko Filistejcev, je bil prestrašen in njegovo srce je silno trepetalo.',
        6: 'Ko je Savel poizvedel od Gospoda, mu Gospod ni odgovoril, niti po sanjah, niti po urimu, niti po prerokih.',
        7: 'Potem je Savel rekel svojim služabnikom: »Poiščite mi žensko, ki ima osebnega duha, da lahko grem k njej in jo povprašam.« Njegov služabnik mu je rekel: »Glej, v En Doru je ženska, ki ima osebnega duha.«',
        8: 'Savel se je preoblekel in si nadel drugo oblačilo in odšel ter dva moža z njim in ponoči so prišli k ženski. Rekel je: »Prosim te, vedežuj mi po osebnem duhu in katerega ti bom imenoval, mi ga privedi gor.«',
        9: 'Ženska mu je rekla: »Glej, ti veš, kaj je storil Savel, kako je iz dežele iztrebil tiste, ki imajo osebne duhove in čarovnike. Zakaj mi potem polagaš zanko za moje življenje, da mi povzročiš, da umrem?«',
        10: 'Savel ji je prisegel pri Gospodu, rekoč: » Kakor živi Gospod, se ti za to stvar ne bo pripetila nobena kazen.«',
        11: 'Potem je ženska rekla: »Koga naj privedem k tebi?« Rekel je: »Privedi mi gor Samuela.«',
        12: 'Ko je ženska zagledala Samuela, je zavpila z močnim glasom. Ženska je spregovorila Savlu, rekoč: »Zakaj si me zavedel? Kajti ti si Savel.«',
        13: 'Kralj ji je rekel: »Ne boj se, kajti kaj si videla?« Ženska je rekla Savlu: »Videla sem bogove vzpenjati se iz zemlje.«',
        14: 'Rekel ji je: »Kakšne oblike je?« Rekla je: »Starec prihaja gor in pokrit je z ogrinjalom.« Savel je zaznal, da je bil to Samuel in se s svojim obrazom sklonil do tal in se priklonil.',
        15: 'Samuel je rekel Savlu: »Zakaj si me vznemiril, da me privedeš gor?« Savel je odgovoril: »Zelo sem zaskrbljen, kajti Filistejci se bojujejo zoper mene, Bog pa je odšel od mene in mi nič več ne odgovarja niti po prerokih niti po sanjah. Zato sem te poklical, da mi lahko daš vedeti, kaj naj storim.«',
        16: 'Potem je Samuel rekel: »Zakaj potem sprašuješ mene, glede na to, da je Gospod odšel od tebe in je postal tvoj sovražnik?',
        17: 'Gospod mu je storil, kakor je govoril po meni, kajti Gospod je iztrgal kraljestvo iz tvoje roke in ga dal tvojemu bližnjemu, torej Davidu,',
        18: 'ker ne ubogaš Gospodovega glasu niti ne izvršuješ njegovega krutega besa nad Amálekom, zato ti je Gospod ta dan storil to stvar.',
        19: 'Poleg tega bo Gospod tudi Izrael s teboj izročil v roko Filistejcev. Jutri boste ti in tvoji sinovi z menoj. Tudi izraelsko vojsko bo Gospod izročil v roko Filistejcev.«',
        20: 'Potem je Savel takoj padel po vsej dolžini na zemljo in bil je boleče prestrašen zaradi Samuelovih besed in v njem ni bilo moči, kajti ves dan ni jedel kruha niti vso noč.',
        21: 'Ženska je prišla k Savlu in videla, da je bil silno vznemirjen in mu rekla: »Glej, tvoja pomočnica je ubogala tvoj glas in svoje življenje sem položila v svojo roko in prisluhnila tvojim besedam, ki si mi jih spregovoril.',
        22: 'Zdaj torej, prosim te, tudi ti prisluhni glasu svoje pomočnice in naj predte postavim grižljaj kruha in jej, da boš lahko imel moč, ko greš na svojo pot.«',
        23: 'Vendar je odklonil in rekel: »Ne bom jedel.« Toda njegovi služabniki so ga, skupaj z žensko, primorali in prisluhnil je njihovemu glasu. Tako je vstal iz tal in sedel na posteljo.',
        24: 'Ženska je imela v hiši rejeno tele. Pohitela je, ga zaklala, vzela moko in jo zgnetla ter iz nje spekla nekvašen kruh.',
        25: 'In to je prinesla pred Savla in pred njegove služabnike in ti so jedli. Potem so vstali in tisto noč odšli proč.',
    },
    29: {
        1: 'Filistejci so torej vse svoje vojske zbrali skupaj k Aféku, Izraelci pa so se utaborili pri studencu, ki je v Jezreélu.',
        2: 'Knezi izmed Filistejcev so šli mimo po stotnijah in po tisočnijah, toda David in njegovi možje so šli mimo v zadnji straži z Ahíšem.',
        3: 'Potem so princi Filistejcev rekli: »Kaj počnejo tukaj ti Hebrejci?« Ahíš je rekel princem Filistejcev: » Ali ni to David, služabnik Savla, Izraelovega kralja, ki je bil z menoj te dni ali ta leta in v njem nisem našel nobenega madeža, odkar je pripadel k meni, do tega dne?«',
        4: 'Filistejski princi pa so bili ogorčeni nad njim in filistejski princi so mu rekli: »Primoraj tega pajdaša, da se vrne, da bo lahko ponovno šel na svoj kraj, ki si mu ga določil in naj ne gre z nami dol v bitko, da nam v bitki ne bi bil nasprotnik, kajti s čim se bo prikupil svojemu gospodarju? Ali naj to ne bi bilo z glavami teh ljudi?«',
        5: 'Ali ni to David, o katerem so druga drugi pele v plesih, rekoč: »Savel je usmrtil svoje tisoče, David pa svoje deset tisoče?«',
        6: 'Potem je Ahíš poklical Davida in mu rekel: »Zagotovo, kakor Gospod živi, si bil pošten in tvoje odhajanje in tvoje prihajanje z menoj v vojsko je dobro v mojem pogledu, kajti nisem našel zla v tebi od dneva tvojega prihoda k meni, do tega dne, pa vendar ti knezi niso naklonjeni.',
        7: 'Zato se sedaj vrni in pojdi v miru, da ne razžališ filistejskih knezov.«',
        8: 'David je rekel Ahíšu: »Toda kaj sem storil? Kaj si našel na svojem služabniku, dokler sem bil s teboj, do tega dne, da se ne smem iti bojevat zoper sovražnike svojega gospoda kralja?«',
        9: 'Ahíš je odgovoril in Davidu rekel: »Vem, da si dober v mojih očeh, kakor Božji angel. Vendar so princi Filistejcev rekli: ›Ta ne bo šel z nami gor v bitko.‹',
        10: 'Zato sedaj vstani zgodaj zjutraj s služabniki svojega gospoda, ki so prišli s teboj in takoj, ko boste zgodaj zjutraj pokonci in imeli svetlobo, odidite.«',
        11: 'Tako so David in njegovi možje zgodaj zjutraj vstali, da odrinejo, da se vrnejo v deželo Filistejcev. Filistejci pa so šli gor k Jezreélu.',
    },
    30: {
        1: 'Pripetilo se je, ko so David in njegovi možje na tretji dan prišli v Ciklág, da so Amalečani napadli jug in Ciklág in udarili Ciklág ter ga požgali z ognjem',
        2: 'in ženske, ki so bile v njem, so zajeli [kot] ujetnice. Nobene niso usmrtili niti velike niti male, temveč so jih odvedli proč in odšli na svojo pot.',
        3: 'Tako so David in njegovi možje prišli k mestu in glej, to je bilo požgano z ognjem. Njihove žene, njihovi sinovi in njihove hčere pa so bili zajeti [kot] ujetniki.',
        4: 'Potem so David in ljudstvo, ki je bilo z njim, povzdignili svoje glasove in jokali, dokler niso imeli več moči za jokanje.',
        5: 'In dve Davidovi ženi sta bili zajeti [kot] ujetnici, Jezreélka Ahinóam in Abigájila, žena Karmelčana Nabála.',
        6: 'David je bil silno zaskrbljen, kajti ljudstvo je govorilo o njegovem kamnanju, ker so bile duše vseh ljudi užaloščene, vsak mož zaradi svojih sinov in zaradi svojih hčera, toda David se je ohrabril v Gospodu, svojem Bogu.',
        7: 'David je duhovniku Abjatárju rekel: »Ahimélehov sin, prosim te, prinesi mi sèm efód.« In Abjatár je tja, k Davidu, prinesel efód.',
        8: 'David je poizvedel pri Gospodu, rekoč: »Ali naj sledim za tem krdelom? Ali jih bom dohitel?« Odgovoril mu je: »Zasleduj, kajti zagotovo jih boš dohitel in čisto gotovo vse povrnil.«',
        9: 'Tako je David odšel, on in šeststo mož, ki so bili z njim in prišli so k potoku Besór, kjer so ostali tisti, ki so ostali zadaj.',
        10: 'Toda David je zasledoval, on in štiristo mož, kajti dvesto jih je ostalo zadaj, ki so bili tako slabotni, da niso mogli prečkati potoka Besór.',
        11: 'Na polju so našli Egipčana, ga privedli k Davidu, mu dali kruha in je jedel in primorali so ga piti vodo.',
        12: 'Dali so mu košček figove kepe in dva grozda rozin. Ko je pojedel, je njegov duh ponovno prišel k njemu, kajti tri dni in tri noči ni jedel nobenega kruha niti ni pil nobene vode.',
        13: 'David mu je rekel: »Komu pripadaš? In od kod si?« Rekel je: »Jaz sem mladenič iz Egipta, služabnik Amálečana in moj gospodar me je pustil, ker sem se pred tremi dnevi počutil bolnega.',
        14: 'Naredili smo invazijo nad jug Keretéjcev in nad območja, ki pripadajo Judu in nad jug Kaléba in Ciklág smo požgali z ognjem.«',
        15: 'David mu je rekel: »Ali me lahko privedeš dol k tej skupini?« Rekel je: »Prisezi mi pri Bogu, da me ne boš niti ubil niti me ne boš izročil rokam mojega gospodarja in jaz te bom odvedel dol k tej skupini.«',
        16: 'Ko ga je privedel dol, glej, bili so razširjeni nad vso zemljo, jedli, pili in plesali zaradi velikega plena, ki so ga vzeli iz filistejske dežele in iz Judove dežele.',
        17: 'David jih je udarjal od večerne polteme do naslednjega dne in niti mož izmed njih ni pobegnil razen štiristo mladeničev, ki so jahali na kamelah in pobegnili.',
        18: 'David je povrnil vse, kar so Amalečani odvedli proč in David je rešil svoji dve ženi.',
        19: 'Ničesar jim ni manjkalo, niti malega, niti velikega, niti sinov, niti hčera, niti plena, niti nobene stvari, ki so jim jih vzeli. Vse je David povrnil.',
        20: 'David je vzel vse trope in črede, ki so jih gnali pred tisto drugo živino in rekli so: »To je Davidov plen.«',
        21: 'David je prišel k dvestotim možem, ki so bili tako slabotni, da niso mogli slediti Davidu, ki so jih primorali, da ostanejo pri potoku Besórju in odšli so naprej, da srečajo Davida in da srečajo ljudstvo, ki je bilo z njim in ko se je David približal ljudstvu, jih je pozdravil.',
        22: 'Potem so odgovorili vsi zlobneži in Beliálovi možje izmed tistih, ki so odšli z Davidom in rekli: »Ker niso odšli z nami, jim ne bomo dali od plena, ki smo ga povrnili, razen vsakemu možu svojo ženo in svoje otroke, da jih bodo lahko odvedli proč in odšli.«',
        23: 'Potem je David rekel: »Ne boste tako storili, moji bratje, s tem, kar nam je Gospod dal, ki nas je zaščitil in v naše roke izročil skupino, ki je prišla zoper nas.',
        24: 'Kajti kdo vam bo prisluhnil v tej zadevi? Temveč kakor je njegov del tistemu, ki gre dol v bitko, tako bo njegov del tistemu, ki ostane pri stvareh. Enako si bosta razdelila.«',
        25: 'In tako je bilo od tega dne naprej, da je to naredil [za] zakon in odredbo za Izraela do tega dne.',
        26: 'Ko je David prišel v Ciklág, je od plena poslal Judovim starešinam, torej svojim prijateljem, rekoč: »Glejte darilo za vas od plena Gospodovih sovražnikov;',
        27: 'tistim, ki so bili v Betelu in tistim, ki so bili v južnem Ramátu in tistim, ki so bili v Jatírju',
        28: 'in tistim, ki so bili v Aroêrju in tistim, ki so bili v Sifmótu in tistim, ki so bili v Eštemói',
        29: 'in tistim, ki so bili v Rahálu in tistim, ki so bili v mestih Jerahmeélovcev in tistim, ki so bili v mestih Kenéjcev',
        30: 'in tistim, ki so bili v Hormi in tistim, ki so bili v Bor Ašánu in tistim, ki so bili v Atáhu',
        31: 'in tistim, ki so bili v Hebrónu in k vsem krajem, kjer so se bili sam David in njegovi možje vajeni preganjati.«',
    },
    31: {
        1: 'Torej Filistejci so se borili zoper Izrael in Izraelci so pobegnili pred Filistejci in padli dol, umorjeni na gori Gilbói.',
        2: 'Filistejci so tesno sledili Savlu in njegovim sinovom in Filistejci so usmrtili Jonatana, Abinadába in Malkišúa, Savlove sinove.',
        3: 'Bitka je postala huda zoper Savla in lokostrelci so ga zadeli; in bil je hudo ranjen od lokostrelcev.',
        4: 'Potem je Savel rekel svojemu nosilcu bojne opreme: »Izvleci svoj meč in me prebodi z njim; da ne bi prišli ti neobrezanci in me prebodli in me zlorabili.« Vendar njegov nosilec bojne opreme ni hotel, kajti bil je hudo prestrašen. Zato je Savel vzel meč in padel nanj.',
        5: 'Ko je njegov nosilec bojne opreme videl, da je bil Savel mrtev, je tudi sam prav tako padel na svoj meč in umrl z njim.',
        6: 'Tako so ta isti dan skupaj umrli Savel, njegovi trije sinovi, njegov nosilec bojne opreme in vsi njegovi možje.',
        7: 'Ko so Izraelovi možje, ki so bili na drugi strani doline in tisti, ki so bili na drugi strani Jordana, videli, da so Izraelovi možje pobegnili in da so bili Savel in njegovi sinovi mrtvi, so zapustili mesta in pobegnili in Filistejci so prišli ter prebivali v njih.',
        8: 'Pripetilo se je naslednji dan, ko so prišli Filistejci, da oropajo umorjene, da so našli Savla in njegove tri sinove padle na gori Gilbói.',
        9: 'Odsekali so njegovo glavo, slekli njegovo bojno opremo in poslali naokoli, v deželo Filistejcev, da to razglasijo v hiši njihovih malikov in med ljudstvom.',
        10: 'Njegovo bojno opremo so položili v hišo Astarte. Njegovo telo pa so pritrdili na obzidje Bet Šeána.',
        11: 'Ko so prebivalci Jabéš Gileáda slišali o tem, kar so Filistejci storili Savlu,',
        12: 'so se vsi hrabri možje vzdignili in hodili vso noč in vzeli Savlovo telo in telesa njegovih sinov z obzidja Bet Šeána in prišli v Jabéš ter jih tam sežgali.',
        13: 'In vzeli so njihove kosti in jih pokopali pod drevesom pri Jabéšu in se postili sedem dni.',
    },
}
